/** Авторская открытая практика. Код ученика здесь не исполняется; fixtures не дают серверный зачёт. */
export type PracticeLanguage = 'python' | 'javascript' | 'rust';
export type PracticeExercise = {
  id: string; topicId: string; title: string; mode: 'guided' | 'transfer';
  prompt: string; formula: string; hints: string[]; explanation: string;
  starter: Record<PracticeLanguage, string>; solution: Record<PracticeLanguage, string>;
  fixtures: { input: string; output: string }[];
  tolerance?: { atol: number; rtol: number };
  evidenceScope?: 'repeat';
  contractNote?: string;
  quiz: { question: string; options: string[]; correctIndex: number; explanation: string };
};
export type PracticeTopic = {
  id: string; lessonId: string; title: string; sourceSection?: string;
  prerequisites: string[]; exercises: PracticeExercise[];
};
export const practiceRelease = '2026-10-v1';

const rustError = '#[derive(Debug, PartialEq)]\npub enum InputError { InvalidInput }\n';
type Samples = Pick<PracticeExercise, 'starter' | 'solution'>;
function samples(py: string, js: string, rs: string, bodies: [string, string, string], structs = ''): Samples {
  const python = (body: string) => {
    // Python bool is an int subclass; public numeric/ID contracts explicitly exclude bool.
    const guarded = body.replaceAll('math.isfinite(', '_finite(')
      .replace(/isinstance\((\w+),int\)/g,'type($1) is int')
      .replace(/(\w+) not in \(0,1\)/g,'(type($1) not in (int,float) or $1 not in (0,1))');
    return `import math\n\n${py}:\n    _finite = lambda value: type(value) in (int, float) and math.isfinite(value)\n${guarded.split('\n').map(line => `    ${line}`).join('\n')}\n`;
  };
  const javascript = (body: string) => `${js} {\n${body.split('\n').map(line => `  ${line}`).join('\n')}\n}\n`;
  const rust = (body: string) => `${rustError}${structs}${rs} {\n${body.split('\n').map(line => `    ${line}`).join('\n')}\n}\n`;
  return {
    starter: { python: python('raise NotImplementedError("Реализуйте формулу и контракт")'), javascript: javascript('throw new Error("Реализуйте формулу и контракт");'), rust: rust('todo!("Реализуйте формулу и контракт")') },
    solution: { python: python(bodies[0]), javascript: javascript(bodies[1]), rust: rust(bodies[2]) },
  };
}
const fixture = (input: unknown, output: unknown) => ({ input: JSON.stringify(input), output: JSON.stringify(output) });
const quiz = (question: string, options: string[], correctIndex: number, explanation: string): PracticeExercise['quiz'] => ({ question, options, correctIndex, explanation });
function exercise(topicId: string, suffix: string, title: string, mode: PracticeExercise['mode'], prompt: string, formula: string, hints: string[], explanation: string, code: Samples, fixtures: PracticeExercise['fixtures'], question: PracticeExercise['quiz']): PracticeExercise {
  return { id: `${topicId}.${suffix}`, topicId, title, mode, prompt, formula, hints, explanation, ...code, fixtures, quiz: question };
}

const softmaxCode = samples('def stable_softmax(logits: list[float]) -> list[float]', 'function stableSoftmax(logits)', 'pub fn stable_softmax(logits: &[f64]) -> Result<Vec<f64>, InputError>', [
  'if not 1 <= len(logits) <= 64 or any(not math.isfinite(x) or abs(x) > 10000 for x in logits):\n    raise ValueError("Ожидаются 1–64 конечных logits в пределах ±10000")\nm = max(logits)\nweights = [math.exp(x - m) for x in logits]\ntotal = sum(weights)\nreturn [p / total for p in weights]',
  'if (!Array.isArray(logits) || logits.length < 1 || logits.length > 64 || logits.some(x => typeof x !== "number" || !Number.isFinite(x) || Math.abs(x) > 10000)) throw new RangeError("Некорректные logits");\nconst maximum = Math.max(...logits);\nconst weights = logits.map(x => Math.exp(x - maximum));\nconst total = weights.reduce((sum, x) => sum + x, 0);\nreturn weights.map(x => x / total);',
  'if logits.is_empty() || logits.len() > 64 || logits.iter().any(|x| !x.is_finite() || x.abs() > 10000.0) { return Err(InputError::InvalidInput); }\nlet maximum = logits.iter().copied().fold(f64::NEG_INFINITY, f64::max);\nlet weights: Vec<f64> = logits.iter().map(|x| (x - maximum).exp()).collect();\nlet total: f64 = weights.iter().sum();\nOk(weights.iter().map(|x| x / total).collect())',
]);
function graphCode(kind: 'base' | 'a' | 'b'): Samples {
  const coefficient = kind === 'a' ? 2 : 1;
  const extra = kind === 'b';
  return samples('def shared_graph_backward(x: float, w: float, b: float) -> dict[str, float]', 'function sharedGraphBackward(x, w, b)', 'pub fn shared_graph_backward(x: f64, w: f64, b: f64) -> Result<GraphResult, InputError>', [
    `if any(not math.isfinite(v) or abs(v) > 4 for v in (x, w, b)):\n    raise ValueError("Конечные x,w,b в пределах ±4")\nq = w * x + b\nloss = q * q + ${coefficient} * q${extra ? ' + w * x' : ''}\ndq = 2 * q + ${coefficient}\nreturn {"q": q, "loss": loss, "dx": dq * w${extra ? ' + w' : ''}, "dw": dq * x${extra ? ' + x' : ''}, "db": dq}`,
    `if ([x, w, b].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v) > 4)) throw new RangeError("Некорректные x,w,b");\nconst q = w * x + b;\nconst loss = q * q + ${coefficient} * q${extra ? ' + w * x' : ''};\nconst dq = 2 * q + ${coefficient};\nreturn { q, loss, dx: dq * w${extra ? ' + w' : ''}, dw: dq * x${extra ? ' + x' : ''}, db: dq };`,
    `if [x, w, b].iter().any(|v| !v.is_finite() || v.abs() > 4.0) { return Err(InputError::InvalidInput); }\nlet q = w * x + b;\nlet loss = q * q + ${coefficient}.0 * q${extra ? ' + w * x' : ''};\nlet dq = 2.0 * q + ${coefficient}.0;\nOk(GraphResult { q, loss, dx: dq * w${extra ? ' + w' : ''}, dw: dq * x${extra ? ' + x' : ''}, db: dq })`,
  ], '#[derive(Debug)]\npub struct GraphResult { pub q: f64, pub loss: f64, pub dx: f64, pub dw: f64, pub db: f64 }\n');
}
const sgdCode = samples('def sgd_step(theta: list[float], grad: list[float], eta: float) -> list[float]', 'function sgdStep(theta, grad, eta)', 'pub fn sgd_step(theta: &[f64], grad: &[f64], eta: f64) -> Result<Vec<f64>, InputError>', [
  'if not theta or len(theta) != len(grad) or not math.isfinite(eta) or not 0 <= eta <= 1 or any(not math.isfinite(v) or abs(v) > 10000 for v in theta + grad):\n    raise ValueError("Формы, конечные параметры и eta в [0,1]")\nreturn [t - eta * g for t, g in zip(theta, grad)]',
  'if (!Array.isArray(theta) || !Array.isArray(grad) || !theta.length || theta.length !== grad.length || typeof eta !== "number" || !Number.isFinite(eta) || eta < 0 || eta > 1 || [...theta, ...grad].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v) > 10000)) throw new RangeError("Некорректный шаг");\nreturn theta.map((t, i) => t - eta * grad[i]);',
  'if theta.is_empty() || theta.len() != grad.len() || !eta.is_finite() || !(0.0..=1.0).contains(&eta) || theta.iter().chain(grad).any(|v| !v.is_finite() || v.abs() > 10000.0) { return Err(InputError::InvalidInput); }\nOk(theta.iter().zip(grad).map(|(t, g)| t - eta * g).collect())',
]);
const softmaxId = 'unit.transformer.attention.softmax';
const sharedId = 'unit.backprop.shared';
const sgdId = 'unit.optimizer.sgd';
const softmaxFormula = 'm = max(z); pᵢ = exp(zᵢ − m) / Σⱼ exp(zⱼ − m)';
const softmaxContract = 'Вход: 1–64 конечных logits в пределах ±10000. Верните новый массив такой же длины, не меняя вход. Пустой, нечисловой или неконечный вход отклоняется: ValueError (wrong type допускает TypeError), RangeError или InputError. Нулевые вероятности из-за underflow допустимы. Сравнение: atol=1e−12, rtol=1e−10.';
const sharedContract = 'Входные x,w,b конечны, |x|,|w|,|b|≤4. Верните q,loss,dx,dw,db; внешний градиент 1. Невалидные значения: ValueError/RangeError/InputError. q не обрезать. Сравнение: atol=1e−12, rtol=1e−10. Это конкретный граф, не общий autograd.';
const sgdContract = 'theta и grad — непустые векторы одинаковой длины, конечные значения в ±10000; eta конечна в [0,1]. Верните новый вектор, не меняя theta/grad. Невалидные данные: ValueError/RangeError/InputError. Сравнение: atol=1e−12, rtol=1e−10. Градиент уже передан: optimizer не вычисляет его заново.';

const anchors: PracticeTopic[] = [
  { id: softmaxId, lessonId: 'transformer', title: 'Устойчивый softmax', sourceSection: 'chapter 1 · attention: нормировка scores', prerequisites: ['concept.exponential', 'concept.probability', 'concept.vector'], exercises: [
    exercise(softmaxId, 'guided', 'Сдвиг → экспоненты → вероятности', 'guided', `Реализуйте stable_softmax. Сначала предскажите [0,0], затем вычислите max, сдвиги и сумму экспонент. Проверьте [1000,1001], singleton и отклонение пустого входа. ${softmaxContract}`, softmaxFormula, ['Из всех logits вычитайте один и тот же максимум: наибольшая экспонента станет 1.', 'Сначала получите весь массив exp(zᵢ−m), затем делите каждое значение на одну общую сумму.'], 'Для [1000,1001] сдвинутые значения −1 и 0. exp(−1)/(1+exp(−1))≈0.26894. Деление logits на их сумму не сохраняет сдвиговую симметрию и может дать отрицательные веса.', softmaxCode, [fixture({logits:[0,0]}, [0.5,0.5]), fixture({logits:[1,2,3]}, [0.09003057317038046,0.24472847105479764,0.6652409557748218]), fixture({logits:[1000,1001]}, [0.2689414213699951,0.7310585786300049]), fixture({logits:[-1000]}, [1])], quiz('Каким станет softmax([0,0]), если к обоим logits прибавить 1000?', ['[1000,1000]', '[0.5,0.5]', '[0,0]', 'Зависит от знака сдвига'], 1, 'Общий множитель exp(1000) сокращается. Вычитание max выполняет это устойчиво.')),
    exercise(softmaxId, 'transfer-a', 'Контроль A · пять классов и общий сдвиг', 'transfer', `У классификатора пять logits. Реализуйте stable_softmax для произвольного допустимого входа и вручную сопоставьте результаты для z=[0,ln(2),ln(4),ln(2),0] и z+1000. Не возвращайте заготовленный ответ. ${softmaxContract}`, softmaxFormula, ['Проверьте отношение весов классов: exp(ln 4)/exp(ln 2)=2.', 'Общий сдвиг должен исчезнуть из каждой разности zᵢ−max(z).'], 'Экспоненты пропорциональны [1,2,4,2,1], сумма 10. Получатся [0.1,0.2,0.4,0.2,0.1] при обоих сдвигах. Сумма 1 сама по себе пропустила бы ошибочный всегда равномерный ответ.', softmaxCode, [fixture({logits:[0,Math.log(2),Math.log(4),Math.log(2),0]},[0.1,0.2,0.4,0.2,0.1]), fixture({logits:[1000,1000+Math.log(2),1000+Math.log(4),1000+Math.log(2),1000]},[0.1,0.2,0.4,0.2,0.1])], quiz('Какое отношение p₃/p₂ у logits [0, ln 2, ln 4, ln 2, 0] (индексы с 1)?', ['1/2','1','2','4'], 2, 'Отношение нормированных вероятностей равно отношению экспонент: 4/2=2.')),
    exercise(softmaxId, 'transfer-b', 'Контроль B · перестановка attention keys', 'transfer', `Получите веса одной строки attention scores [ln(3),0,ln(2)] без маски. Затем переставьте keys в порядке [2,0,1] (индексы с 0). Реализуйте ту же функцию для любой длины по контракту и проверьте, что веса переставились вместе с keys. ${softmaxContract}`, softmaxFormula, ['Это softmax по keys одной строки, не по нескольким query одновременно.', 'Знаменатель суммы не меняется от перестановки; числители переезжают вместе с scores.'], 'Исходные weights [1/2,1/6,1/3], переставленные [1/3,1/2,1/6]. Индекс key — порядок элемента, не новая пространственная координата.', softmaxCode, [fixture({logits:[Math.log(3),0,Math.log(2)]},[0.5,1/6,1/3]), fixture({logits:[Math.log(2),Math.log(3),0]},[1/3,0.5,1/6])], quiz('После перестановки keys [2,0,1] куда переедет вес исходного key 0?', ['Останется на позиции 0','На позицию 1','На позицию 2','Все веса станут одинаковыми'], 1, 'На позиции 1 теперь стоит исходный key 0, поэтому его вес переезжает туда.')),
  ] },
  { id: sharedId, lessonId: 'backprop', title: 'Backward у общего узла', sourceSection: 'shared graph', prerequisites: ['unit.neuron.affine','concept.derivative','concept.chain-rule'], exercises: [
    exercise(sharedId,'guided','Сложить два пути от q к loss','guided', `Напишите forward q=w*x+b, L=q²+q, затем backward. К q идут две ветви: квадрат и прямое сложение. Сложите их вклады до умножения на локальные производные affine. Проверьте q=−0.5 и x=0. ${sharedContract}`, 'q=wx+b; L=q²+q; dq=2q+1; dx=dq·w; dw=dq·x; db=dq', ['Производная квадрата берётся в q, а не в x.', 'Прямая ветвь q добавляет 1. При q=−0.5 вклады −1 и +1 взаимно уничтожаются.'], 'Для x=2,w=3,b=1: q=7,L=56,dq=15,dx=45,dw=30,db=15. Каждый путь даёт вклад; перезапись dq вместо сложения теряет ветвь.', graphCode('base'), [fixture({x:2,w:3,b:1},{q:7,loss:56,dx:45,dw:30,db:15}),fixture({x:1,w:-1,b:0.5},{q:-0.5,loss:-0.25,dx:0,dw:0,db:0}),fixture({x:0,w:2,b:1},{q:1,loss:2,dx:6,dw:0,db:3})],quiz('Чему равен dL/dq при q=2 и L=q²+q?', ['4','5','6','8'],1,'От квадрата приходит 2q=4, от прямой ветви — 1. Сумма 5.')),
    exercise(sharedId,'transfer-a','Контроль A · изменённая прямая ветвь','transfer', `Теперь L=q²+2q при прежнем q=wx+b. Реализуйте shared_graph_backward для нового графа. Старое +1 в dq больше не подходит. ${sharedContract}`, 'L=q²+2q; dq=2q+2; dx=dq·w; dw=dq·x; db=dq', ['Производная 2q по q равна 2.', 'Нулевая чувствительность теперь при q=−1, а не −0.5.'], 'При x=1,w=−2,b=1: q=−1,L=−1; все градиенты нулевые. При x=2,w=1,b=0: q=2,L=8,dq=6. Изменение forward требует изменения backward.', graphCode('a'), [fixture({x:1,w:-2,b:1},{q:-1,loss:-1,dx:0,dw:0,db:0}),fixture({x:2,w:1,b:0},{q:2,loss:8,dx:6,dw:12,db:6})],quiz('В какой точке d(q²+2q)/dq=0?', ['q=−1','q=−0.5','q=0','q=1'],0,'2q+2=0 даёт q=−1.')),
    exercise(sharedId,'transfer-b','Контроль B · дополнительный путь к x и w','transfer', `Добавьте r=wx и L=q²+q+r. Верните прежние пять полей. Через r появляется ещё один путь к x и w, но не к b. ${sharedContract}`, 'q=wx+b; r=wx; L=q²+q+r; dq=2q+1; dx=dq·w+w; dw=dq·x+x; db=dq', ['Сначала посчитайте градиенты через q как раньше.', 'r=wx добавляет w к dx и x к dw. У r нет зависимости от b.'], 'При x=1,w=2,b=−1: q=1,L=4,dq=3. Через q: dx=6,dw=3; через r: ещё 2 и 1. Поэтому dx=8,dw=4,db=3.', graphCode('b'), [fixture({x:1,w:2,b:-1},{q:1,loss:4,dx:8,dw:4,db:3}),fixture({x:2,w:-1,b:0.5},{q:-1.5,loss:-1.25,dx:1,dw:-2,db:-2})],quiz('Какой градиент не получает дополнительного вклада от r=wx?', ['dx','dw','db','Все получают'],2,'r не зависит от b, поэтому его частная производная по b равна 0.')),
  ] },
  { id: sgdId, lessonId: 'optimizers', title: 'Один шаг SGD', sourceSection: 'SGD method', prerequisites: ['concept.gradient','concept.vector'], exercises: [
    exercise(sgdId,'guided','Градиент и шаг имеют разные знаки','guided', `Напишите sgd_step по готовому градиенту. Для theta=[2,1],grad=[2,8],eta=0.1 вычислите отдельно delta=−eta*grad. Проверьте eta=0, нулевой grad и ошибку форм. ${sgdContract}`, 'θ_new = θ − ηg; Δθ=−ηg', ['Положительная производная означает рост loss при росте параметра; шаг должен уменьшить параметр.', 'При eta=0 верните новый массив с прежними значениями.'], 'delta=[−0.2,−0.8], theta_new=[1.8,0.2]. На L=(x²+8y²)/2 это меняет loss с 6 до 1.78. Сам SGD не знает эту loss и не гарантирует снижение при любом eta.', sgdCode, [fixture({theta:[2,1],grad:[2,8],eta:0.1},[1.8,0.2]),fixture({theta:[2,1],grad:[2,8],eta:0.3},[1.4,-1.4]),fixture({theta:[1,-2],grad:[0,3],eta:0},[1,-2])],quiz('theta=3, grad=−2, eta=0.1. Каков новый параметр?', ['2.8','3.2','−0.2','−3.2'],1,'3−0.1·(−2)=3.2. Отрицательный gradient увеличивает параметр.')),
    exercise(sgdId,'transfer-a','Контроль A · слишком большой шаг на quadratic','transfer', `Для L=(x²+8y²)/2, theta=[2,1] вычислите grad=[x,8y]. Реализуйте sgd_step и сравните eta=0.1 и eta=0.3. Новую loss вычисляйте отдельно; правильный большой шаг обязан показать рост. ${sgdContract}`, 'L=(x²+8y²)/2; ∇L=[x,8y]; θ_new=θ−η∇L', ['Подставьте новые x,y в исходную quadratic, не в линейное приближение.', 'lambda_max=8. Гарантированный диапазон для этой quadratic: 0<eta<2/8.'], 'eta=.1 даёт [1.8,.2] и L=1.78; eta=.3 даёт [1.4,−1.4] и L=8.82. Большой шаг перелетает по крутой координате y. Рост loss здесь не ошибка реализации update.', sgdCode, [fixture({theta:[2,1],grad:[2,8],eta:0.1},[1.8,0.2]),fixture({theta:[2,1],grad:[2,8],eta:0.3},[1.4,-1.4])],quiz('Какая пара новых loss соответствует eta=.1 и .3?', ['1.78 и 8.82','Обе меньше 6','8.82 и 1.78','1.78 и 1.78'],0,'Вычисление по исходной quadratic даёт 1.78 и 8.82.')),
    exercise(sgdId,'transfer-b','Контроль B · другая кривизна и пересчёт градиента','transfer', `На L=(3x²+12y²)/2 возьмите theta=[2,−1]. Реализуйте sgd_step. Сравните eta=.1 и .2 и объясните границу 2/12. Для второго шага eta=.1 пересчитайте gradient в новых параметрах. ${sgdContract}`, 'L=(3x²+12y²)/2; ∇L=[3x,12y]; 0<η<2/λ_max=1/6', ['Первый gradient [6,−12]. После первого малого шага параметры [1.4,.2].', 'На втором шаге gradient уже [4.2,2.4], а не старый [6,−12].'], 'При eta=.1 loss 12→3.18, при eta=.2 — 12→12.72. Повторный малый шаг даёт [.98,−.04] и loss 1.4502. Граница относится к данной положительно определённой quadratic, не ко всем нейросетям.', sgdCode, [fixture({theta:[2,-1],grad:[6,-12],eta:0.1},[1.4,0.2]),fixture({theta:[2,-1],grad:[6,-12],eta:0.2},[0.8,1.4]),fixture({theta:[1.4,0.2],grad:[4.2,2.4],eta:0.1},[0.98,-0.04])],quiz('Какой eta обеспечивает снижение этой quadratic для любого ненулевого theta?', ['eta=.2','eta=.5','eta=.1','Любой eta∈[0,1]'],2,'Для lambda_max=12 нужно 0<eta<1/6. Из вариантов подходит .1.')),
  ] },
];

const dotCode = samples('def dot(x: list[float], w: list[float]) -> float','function dot(x, w)','pub fn dot(x: &[f64], w: &[f64]) -> Result<f64, InputError>',[
  'if not 1 <= len(x) <= 64 or len(x) != len(w) or any(not math.isfinite(v) or abs(v) > 10000 for v in x + w):\n    raise ValueError("Несовместимые конечные векторы")\nreturn sum(a * b for a, b in zip(x, w))',
  'if (!Array.isArray(x) || !Array.isArray(w) || !x.length || x.length > 64 || x.length !== w.length || [...x,...w].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v)>10000)) throw new RangeError("Несовместимые векторы");\nreturn x.reduce((sum, v, i) => sum + v * w[i], 0);',
  'if x.is_empty() || x.len() > 64 || x.len() != w.len() || x.iter().chain(w).any(|v| !v.is_finite() || v.abs()>10000.0) { return Err(InputError::InvalidInput); }\nOk(x.iter().zip(w).map(|(a,b)| a*b).sum())',
]);
const affineCode = samples('def affine(x: list[float], w: list[float], b: float) -> float','function affine(x, w, b)','pub fn affine(x: &[f64], w: &[f64], b: f64) -> Result<f64, InputError>',[
  'if not 1 <= len(x) <= 64 or len(x) != len(w) or any(not math.isfinite(v) or abs(v) > 10000 for v in x + w + [b]):\n    raise ValueError("Несовместимые конечные векторы и bias")\nreturn sum(a * c for a, c in zip(x, w)) + b',
  'if (!Array.isArray(x) || !Array.isArray(w) || !x.length || x.length > 64 || x.length !== w.length || [...x,...w,b].some(v => typeof v !== "number" || !Number.isFinite(v) || Math.abs(v)>10000)) throw new RangeError("Некорректный affine");\nreturn x.reduce((sum, v, i) => sum + v * w[i], b);',
  'if x.is_empty() || x.len() > 64 || x.len() != w.len() || !b.is_finite() || b.abs()>10000.0 || x.iter().chain(w).any(|v| !v.is_finite() || v.abs()>10000.0) { return Err(InputError::InvalidInput); }\nOk(x.iter().zip(w).map(|(a,c)| a*c).sum::<f64>() + b)',
]);
const reluCode = samples('def relu_and_grad(z: float) -> list[float]','function reluAndGrad(z)','pub fn relu_and_grad(z: f64) -> Result<Vec<f64>, InputError>',[
  'if not math.isfinite(z) or abs(z) > 10000:\n    raise ValueError("Конечный z в ±10000")\nreturn [max(0.0, z), 1.0 if z > 0 else 0.0]',
  'if (typeof z !== "number" || !Number.isFinite(z) || Math.abs(z)>10000) throw new RangeError("Некорректный z");\nreturn [Math.max(0,z), z>0 ? 1 : 0];',
  'if !z.is_finite() || z.abs()>10000.0 { return Err(InputError::InvalidInput); }\nOk(vec![z.max(0.0), if z>0.0 {1.0} else {0.0}])',
]);
const denseCode = samples('def dense_batch(x: list[list[float]], w: list[list[float]], b: list[float]) -> list[list[float]]','function denseBatch(x, w, b)','pub fn dense_batch(x: &[Vec<f64>], w: &[Vec<f64>], b: &[f64]) -> Result<Vec<Vec<f64>>, InputError>',[
  'if not x or not w or not x[0] or max(len(x), len(w), len(x[0])) > 64 or len(w) != len(b):\n    raise ValueError("Оси B,I,O должны быть 1–64")\nwidth = len(x[0])\nif any(len(row) != width for row in x + w) or any(not math.isfinite(v) or abs(v)>10000 for row in x + w + [b] for v in row):\n    raise ValueError("Несовместимые строки")\nreturn [[sum(a*c for a,c in zip(row, weights)) + bias for weights,bias in zip(w,b)] for row in x]',
  'if (!Array.isArray(x) || !Array.isArray(w) || !Array.isArray(b) || !x.length || !w.length || !Array.isArray(x[0]) || !x[0].length || Math.max(x.length,w.length,x[0].length)>64 || w.length!==b.length) throw new RangeError("Некорректные оси");\nconst width=x[0].length;\nif ([...x,...w].some(row=>!Array.isArray(row)||row.length!==width) || [...x.flat(),...w.flat(),...b].some(v=>typeof v!=="number"||!Number.isFinite(v)||Math.abs(v)>10000)) throw new RangeError("Некорректные строки");\nreturn x.map(row=>w.map((weights,j)=>row.reduce((sum,v,i)=>sum+v*weights[i],b[j])));',
  'if x.is_empty() || w.is_empty() || x[0].is_empty() || x.len()>64 || w.len()>64 || x[0].len()>64 || w.len()!=b.len() { return Err(InputError::InvalidInput); }\nlet width=x[0].len();\nif x.iter().chain(w).any(|row|row.len()!=width) || x.iter().chain(w).flatten().chain(b).any(|v|!v.is_finite()||v.abs()>10000.0) { return Err(InputError::InvalidInput); }\nOk(x.iter().map(|row|w.iter().zip(b).map(|(weights,bias)|row.iter().zip(weights).map(|(a,c)|a*c).sum::<f64>()+bias).collect()).collect())',
]);
const mseCode = samples('def mse_loss(predictions: list[float], targets: list[float]) -> float','function mseLoss(predictions, targets)','pub fn mse_loss(predictions: &[f64], targets: &[f64]) -> Result<f64, InputError>',[
  'if not 1 <= len(predictions) <= 64 or len(predictions) != len(targets) or any(not math.isfinite(v) or abs(v)>10000 for v in predictions+targets):\n    raise ValueError("Непустые согласованные predictions/targets")\nreturn sum((p-t)**2 for p,t in zip(predictions,targets))/len(predictions)',
  'if (!Array.isArray(predictions)||!Array.isArray(targets)||!predictions.length||predictions.length>64||predictions.length!==targets.length||[...predictions,...targets].some(v=>typeof v!=="number"||!Number.isFinite(v)||Math.abs(v)>10000)) throw new RangeError("Некорректные predictions/targets");\nreturn predictions.reduce((sum,p,i)=>sum+(p-targets[i])**2,0)/predictions.length;',
  'if predictions.is_empty() || predictions.len()>64 || predictions.len()!=targets.len() || predictions.iter().chain(targets).any(|v|!v.is_finite()||v.abs()>10000.0) { return Err(InputError::InvalidInput); }\nOk(predictions.iter().zip(targets).map(|(p,t)|(p-t).powi(2)).sum::<f64>()/predictions.len() as f64)',
]);
const bceCode = samples('def bce_logit(z: float, y: float) -> float','function bceLogit(z, y)','pub fn bce_logit(z: f64, y: f64) -> Result<f64, InputError>',[
  'if not math.isfinite(z) or abs(z)>10000 or y not in (0,1):\n    raise ValueError("Конечный z в ±10000 и y∈{0,1}")\nreturn max(z,0.0)-z*y+math.log1p(math.exp(-abs(z)))',
  'if (typeof z!=="number"||!Number.isFinite(z)||Math.abs(z)>10000||(y!==0&&y!==1)) throw new RangeError("Некорректный logit/label");\nreturn Math.max(z,0)-z*y+Math.log1p(Math.exp(-Math.abs(z)));',
  'if !z.is_finite() || z.abs()>10000.0 || (y!=0.0 && y!=1.0) { return Err(InputError::InvalidInput); }\nOk(z.max(0.0)-z*y+(-z.abs()).exp().ln_1p())',
]);
const finiteCode = samples('def central_gradient(x: float, w: float, b: float, h: float) -> list[float]','function centralGradient(x, w, b, h)','pub fn central_gradient(x: f64, w: f64, b: f64, h: f64) -> Result<Vec<f64>, InputError>',[
  'if any(not math.isfinite(v) or abs(v)>4 for v in (x,w,b)) or not math.isfinite(h) or not 1e-6<=h<=1e-4:\n    raise ValueError("x,w,b в ±4 и h∈[1e−6,1e−4]")\ndef loss(a,c,d):\n    q=c*a+d\n    return q*q+q\npoint=[x,w,b]\nresult=[]\nfor i in range(3):\n    plus=point.copy(); minus=point.copy()\n    plus[i]+=h; minus[i]-=h\n    result.append((loss(*plus)-loss(*minus))/(2*h))\nreturn result',
  'if ([x,w,b].some(v=>typeof v!=="number"||!Number.isFinite(v)||Math.abs(v)>4)||typeof h!=="number"||!Number.isFinite(h)||h<1e-6||h>1e-4) throw new RangeError("Некорректная точка/h");\nconst loss=(a,c,d)=>{const q=c*a+d;return q*q+q;};\nconst point=[x,w,b];\nreturn point.map((_,i)=>{const plus=[...point],minus=[...point];plus[i]+=h;minus[i]-=h;return (loss(...plus)-loss(...minus))/(2*h);});',
  'if [x,w,b].iter().any(|v|!v.is_finite()||v.abs()>4.0) || !h.is_finite() || !(1e-6..=1e-4).contains(&h) { return Err(InputError::InvalidInput); }\nlet loss=|p: [f64;3]|{let q=p[1]*p[0]+p[2];q*q+q};\nlet point=[x,w,b];\nOk((0..3).map(|i|{let mut plus=point;let mut minus=point;plus[i]+=h;minus[i]-=h;(loss(plus)-loss(minus))/(2.0*h)}).collect())',
]);
const momentumCode = samples('def momentum_step(theta: float, velocity: float, grad: float, eta: float, beta: float) -> list[float]','function momentumStep(theta, velocity, grad, eta, beta)','pub fn momentum_step(theta: f64, velocity: f64, grad: f64, eta: f64, beta: f64) -> Result<Vec<f64>, InputError>',[
  'if any(not math.isfinite(v) or abs(v)>10000 for v in (theta,velocity,grad)) or not math.isfinite(eta) or not 0<=eta<=1 or not math.isfinite(beta) or not 0<=beta<1:\n    raise ValueError("Некорректный momentum state")\nnew_velocity=beta*velocity+grad\nreturn [theta-eta*new_velocity,new_velocity]',
  'if ([theta,velocity,grad].some(v=>typeof v!=="number"||!Number.isFinite(v)||Math.abs(v)>10000)||typeof eta!=="number"||!Number.isFinite(eta)||eta<0||eta>1||typeof beta!=="number"||!Number.isFinite(beta)||beta<0||beta>=1) throw new RangeError("Некорректный momentum state");\nconst newVelocity=beta*velocity+grad;\nreturn [theta-eta*newVelocity,newVelocity];',
  'if [theta,velocity,grad].iter().any(|v|!v.is_finite()||v.abs()>10000.0) || !eta.is_finite() || !(0.0..=1.0).contains(&eta) || !beta.is_finite() || !(0.0..1.0).contains(&beta) { return Err(InputError::InvalidInput); }\nlet new_velocity=beta*velocity+grad;\nOk(vec![theta-eta*new_velocity,new_velocity])',
]);
const basicsContract = 'Векторы — непустые, длина 1–64, формы совпадают, числа конечны в ±10000; исходные данные не менять. Невалидный вход: ValueError/RangeError/InputError (Python wrong types может дать TypeError). Сравнение atol=1e−12, rtol=1e−10.';
const foundations: PracticeTopic[] = [
  {id:'concept.dot-product',lessonId:'math',title:'Скалярное произведение',sourceSection:'concept dot-product',prerequisites:['concept.vector'],exercises:[
    exercise('concept.dot-product','guided','Попарно умножить и сложить','guided',`Напишите dot(x,w). В [1,2]·[3,4] не складывайте элементы перед умножением. ${basicsContract}`,'x·w=Σᵢxᵢwᵢ',['Вычислите вклады 1·3 и 2·4 отдельно.','zip допустим только после проверки одинаковой длины.'],'3+8=11. (1+2)(3+4)=21 — другая операция с лишними перекрёстными членами.',dotCode,[fixture({x:[1,2],w:[3,4]},11),fixture({x:[-2,0,3],w:[4,5,-1]},-11)],quiz('Чему равно [2,−1]·[3,4]?',['2','10','7','−2'],0,'2·3+(−1)·4=2.')),
    exercise('concept.dot-product','transfer-a','Контроль A · ортогональные направления','transfer',`Проверьте dot для [1,1] и [1,−1], а затем для перестановки обеих координат. ${basicsContract}`,'x·w=Σᵢxᵢwᵢ',['Отрицательные вклады не надо брать по модулю.'],'1−1=0; согласованная перестановка сохраняет результат. Нулевой dot не означает нулевые векторы.',dotCode,[fixture({x:[1,1],w:[1,-1]},0),fixture({x:[1,1],w:[-1,1]},0)],quiz('Нулевой dot обязательно означает, что один вектор нулевой?',['Да','Нет: направления могут быть ортогональны','Только при длине 2'],1,'Например, [1,1] и [1,−1] оба ненулевые, но их dot равен 0.')),
  ]},
  {id:'unit.neuron.affine',lessonId:'neuron',title:'Взвешенная сумма и bias',sourceSection:'neuron-result',prerequisites:['concept.dot-product'],exercises:[
    exercise('unit.neuron.affine','guided','Добавить bias один раз','guided',`Реализуйте affine(x,w,b). bias добавляется к полной сумме, не к каждому произведению. ${basicsContract}`,'z=Σᵢxᵢwᵢ+b',['Сначала найдите dot, затем прибавьте b один раз.'],'[1,2]·[2,−1]+3=0+3=3. У нулевого x выход b, а не 0.',affineCode,[fixture({x:[1,2],w:[2,-1],b:3},3),fixture({x:[0,0],w:[4,-2],b:5},5)],quiz('При x=[0,0], w=[7,8], b=−3 чему равен z?',['0','−3','15','12'],1,'Нулевые входы убирают weighted sum, но сохраняют bias.')),
    exercise('unit.neuron.affine','transfer-a','Контроль A · подобрать bias под новый target','transfer',`Для x=[2,−1],w=[3,4] нужен z=10. Сначала найдите b, затем реализуйте affine и подтвердите результат. ${basicsContract}`,'b=z_target−x·w',['Weighted sum равна 6−4=2.'],'Нужен b=10−2=8. Это постоянный сдвиг affine; weights менять не требуется.',affineCode,[fixture({x:[2,-1],w:[3,4],b:8},10)],quiz('Какой bias даёт z=10 при weighted sum=2?',['−8','8','12','5'],1,'10−2=8.')),
  ]},
  {id:'unit.neuron.activation.relu',lessonId:'neuron',title:'ReLU и локальная производная',sourceSection:'neuron-activation · ReLU',prerequisites:['concept.derivative'],exercises:[
    exercise('unit.neuron.activation.relu','guided','Передать положительный сигнал','guided','Напишите relu_and_grad(z), возвращающую [activation, derivative]. z конечен в ±10000. В нуле явно принимаем derivative=0; обычная производная там не существует. Невалидный z отклоняется.','ReLU(z)=max(0,z); g(z)=1 при z>0, иначе 0',['Значение и производная — разные величины.','Ветвь z>0, а не z≥0.'],'При z=3 ответ [3,1], при z=−2 — [0,0], при z=0 — [0,0] по выбранной convention.',reluCode,[fixture({z:3},[3,1]),fixture({z:-2},[0,0]),fixture({z:0},[0,0])],quiz('Какова производная ReLU в точке z=5?',['5','1','0','Не существует'],1,'На положительной полуоси ReLU(z)=z и наклон равен 1.')),
    exercise('unit.neuron.activation.relu','transfer-a','Контроль A · мёртвая отрицательная ветвь','transfer','Передайте в relu_and_grad отрицательное preactivation z=−7, затем z=0.2. Для incoming gradient=3 вручную умножьте его на локальную derivative. Контракт конечных z и convention в нуле прежний.','dL/dz=(dL/da)·g(z)',['В отрицательной ветви ReLU output и локальная derivative равны 0.'],'Для −7 градиент по z равен 0; для .2 — 3. ReLU не возвращает incoming gradient: его умножают вне функции.',reluCode,[fixture({z:-7},[0,0]),fixture({z:0.2},[0.2,1])],quiz('Incoming gradient=3, z=−7. Чему равен gradient по z?',['−21','3','0','−7'],2,'3·0=0.')),
  ]},
  {id:'unit.neuron.dense',lessonId:'neuron',title:'Linear для пакета',sourceSection:'neuron-batch',prerequisites:['concept.dot-product','concept.matrix','concept.tensor'],exercises:[
    exercise('unit.neuron.dense','guided','Сохранить оси batch и output','guided',`Напишите dense_batch(X,W,b), где X имеет B×I, W — O×I, b — O; результат B×O. Оси B,I,O от 1 до 64, все строки одинаковой ширины I. ${basicsContract}`,'Yⱼₖ=ΣᵢXⱼᵢWₖᵢ+bₖ',['Для каждой строки X вычислите dot с каждой строкой W.','Bias выбирается по output k, не по batch j.'],'При X=[[1,2],[−1,0]], W=[[2,3],[−1,4],[0,2]], b=[1,−2,3] выход [[9,5,7],[−1,−1,3]].',denseCode,[fixture({x:[[1,2],[-1,0]],w:[[2,3],[-1,4],[0,2]],b:[1,-2,3]},[[9,5,7],[-1,-1,3]])],quiz('X: 4×2, W: 3×2, b:3. Какова форма выхода?',['4×3','3×4','4×2','2×3'],0,'Четыре примера, три выходных признака каждый.')),
    exercise('unit.neuron.dense','transfer-a','Контроль A · перестановка batch','transfer',`Поменяйте две строки пакета местами. Реализуйте dense_batch: строки результата должны поменяться местами, weights/bias остаются прежними. ${basicsContract}`,'f(PX)=P f(X) для перестановки строк P',['Каждый пример обрабатывается независимо от соседей.'],'Перестановка batch не смешивает признаки. Это индекс примера, не физическая координата.',denseCode,[fixture({x:[[-1,0],[1,2]],w:[[2,3],[-1,4],[0,2]],b:[1,-2,3]},[[-1,-1,3],[9,5,7]]),fixture({x:[[0,0]],w:[[2,3],[-1,4]],b:[1,-2]},[[1,-2]])],quiz('Изменение только первой строки X должно изменить…',['Все строки Y','Только первую строку Y','Weights','Размер batch'],1,'Linear применяется к каждому примеру отдельно.')),
  ]},
  {id:'unit.loss.mse',lessonId:'loss',title:'MSE и средняя ошибка',sourceSection:'MSE section',prerequisites:['concept.vector'],exercises:[
    exercise('unit.loss.mse','guided','Квадраты ошибок и mean reduction','guided',`Реализуйте mse_loss(predictions,targets) без множителя 1/2. Квадраты сначала складываются, затем делятся на n. ${basicsContract}`,'MSE=(1/n)Σᵢ(pᵢ−tᵢ)²',['Сначала найдите разности [1,2] для p=[1,3],t=[0,1].','Mean и sum отличаются в n раз.'],'Квадраты [1,4], MSE=2.5. Знак ошибки исчезает при возведении в квадрат, но не при вычислении gradient.',mseCode,[fixture({predictions:[1,3],targets:[0,1]},2.5),fixture({predictions:[2],targets:[-1]},9)],quiz('Для ошибок [1,−3] mean squared error равна…',['−1','4','5','10'],2,'(1²+(−3)²)/2=5.')),
    exercise('unit.loss.mse','transfer-a','Контроль A · дублирование пакета','transfer',`Реализуйте mse_loss и сравните исходный пакет и его двойную копию. Mean должна сохраниться. Объясните, почему сумма выросла бы вдвое. ${basicsContract}`,'mean([e²,e²])=mean(e²)',['И числитель, и длина увеличиваются вдвое.'],'Оба пакета дают 2.5. Проверка отличает mean от sum; правильная mean также чувствительна к величине ошибок.',mseCode,[fixture({predictions:[1,3,1,3],targets:[0,1,0,1]},2.5),fixture({predictions:[0,4],targets:[0,0]},8)],quiz('Как меняется MSE при точном дублировании всех примеров?',['Вдвое больше','Вдвое меньше','Не меняется','Становится 0'],2,'Вдвое больше квадратов делятся на вдвое большее n.')),
  ]},
  {id:'unit.loss.bce',lessonId:'loss',title:'Binary cross-entropy из logits',sourceSection:'BCE section',prerequisites:['concept.probability','concept.logarithm'],exercises:[
    exercise('unit.loss.bce','guided','Устойчивая loss без log(0)','guided','Реализуйте bce_logit(z,y). z конечен в ±10000, label y строго 0 или 1. Используйте log1p и exp(−abs(z)); не вычисляйте sigmoid и затем log округлённой вероятности. Невалидные данные отклоняются.','BCE(z,y)=max(z,0)−zy+log(1+exp(−|z|))',['В exp попадает неположительный аргумент.','log1p(x) точнее log(1+x), когда x мал.'],'При z=0 оба labels дают ln2. При z=1000,y=0 loss≈1000, при y=1≈0, без Infinity/NaN.',bceCode,[fixture({z:0,y:0},Math.LN2),fixture({z:0,y:1},Math.LN2),fixture({z:1000,y:0},1000),fixture({z:1000,y:1},0)],quiz('Уверенный logit z=1000, но label=0. Какова loss примерно?',['0','ln2','1000','−1000'],2,'Уверенная ошибка сильно штрафуется; logit-формула остаётся конечной.')),
    exercise('unit.loss.bce','transfer-a','Контроль A · сменить смысл класса','transfer','Сравните (z=ln3,y=1) и (z=−ln3,y=0): реализуйте bce_logit с прежним контрактом и проверьте равенство. При смене класса одновременно меняются знак logit и label.','BCE(z,y)=BCE(−z,1−y)',['Sigmoid(ln3)=3/4.','Loss верного label — −ln(3/4).'],'Обе loss равны ln(4/3)≈.287682. Смена только знака или только label не сохраняет loss.',bceCode,[fixture({z:Math.log(3),y:1},Math.log(4/3)),fixture({z:-Math.log(3),y:0},Math.log(4/3))],quiz('Что надо изменить вместе с z→−z, чтобы loss сохранилась?',['Ничего','y→1−y','y→−y','eta'],1,'Это смена нумерации двух классов.')),
  ]},
  {id:'unit.backprop.check',lessonId:'backprop',title:'Независимая проверка градиента',sourceSection:'finite difference',prerequisites:['unit.backprop.shared','concept.partial-derivative'],exercises:[
    exercise('unit.backprop.check','guided','Центральная разность по одной координате','guided','Напишите central_gradient(x,w,b,h) для L=(wx+b)²+(wx+b). Верните [dx,dw,db]. Меняйте одну координату на ±h, остальные фиксируйте. x,w,b конечны в ±4, h∈[1e−6,1e−4]. Не вызывайте аналитический backward. Сравнение finite difference atol=1e−7,rtol=1e−6.','∂L/∂θᵢ≈[L(θ+h·eᵢ)−L(θ−h·eᵢ)]/(2h)',['Копируйте точку отдельно для plus и minus.','Знаменатель 2h, не h.'],'При [x,w,b]=[2,3,1] центральная разность должна приблизиться к [45,30,15]. Для гладкого полинома это независимая проверка, а не повторение формулы backward.',finiteCode,[fixture({x:2,w:3,b:1,h:0.00001},[45,30,15]),fixture({x:1,w:-1,b:0.5,h:0.00001},[0,0,0])],quiz('Для частной derivative по w что меняется при двух forward вызовах?',['Все x,w,b','Только w на ±h','Только x','Только loss вручную'],1,'Частная derivative удерживает прочие координаты фиксированными.')),
    exercise('unit.backprop.check','transfer-a','Контроль A · знак и разные масштабы h','transfer','Проверьте central_gradient в новой точке x=−1,w=2,b=.5 для h=1e−4 и 1e−6. Контракт прежний. Не применяйте такой smooth test к ReLU kink в нуле.','q=−1.5; dq=−2; [dx,dw,db]=[−4,2,−2]',['Оба h должны дать согласованные gradients в допуске.'],'По w gradient положительный, по x и b — отрицательный. Слишком малый h вообще может усилить roundoff; h не означает универсальную точность.',finiteCode,[fixture({x:-1,w:2,b:0.5,h:0.0001},[-4,2,-2]),fixture({x:-1,w:2,b:0.5,h:0.000001},[-4,2,-2])],quiz('Можно ли центральной разностью в ReLU(0) подтвердить обычную derivative?',['Да, при любом h','Нет: в 0 обычная derivative не существует','Да: derivative всегда 0'],1,'Центральная разность даст .5, но это не derivative и не выбранная convention 0.')),
  ]},
  {id:'unit.optimizer.momentum',lessonId:'optimizers',title:'Momentum и история движения',sourceSection:'momentum method',prerequisites:['unit.optimizer.sgd'],exercises:[
    exercise('unit.optimizer.momentum','guided','Сохранить velocity между шагами','guided','Напишите scalar momentum_step(theta,velocity,grad,eta,beta) → [new_theta,new_velocity]. Convention: v_new=beta*v+g (без 1−beta). theta,v,g конечны в ±10000; eta∈[0,1], beta∈[0,1). Невалидные данные отклоняются.','v_new=βv+g; θ_new=θ−ηv_new',['Обновление theta использует новую velocity.','При beta=0 правило совпадает с SGD.'],'При theta=2,v=0,g=2,eta=.1,beta=.9 получаем [1.8,2]. На следующем шаге v нельзя снова сбросить в 0.',momentumCode,[fixture({theta:2,velocity:0,grad:2,eta:0.1,beta:0.9},[1.8,2]),fixture({theta:1.8,velocity:2,grad:1.8,eta:0.1,beta:0.9},[1.44,3.6])],quiz('v=2, beta=.9, новый g=−1. Чему равна v_new?',['−1','0.8','−0.8','2.8'],1,'0.9·2−1=.8. История сохраняет прежнее направление.')),
    exercise('unit.optimizer.momentum','transfer-a','Контроль A · разворот gradient','transfer','В новой точке gradient сменил знак: theta=1,v=3,g=−2,eta=.1,beta=.9. Реализуйте momentum_step по прежней convention и объясните, почему theta ещё может двигаться в старую сторону.','v_new=.9·3−2=.7; θ_new=1−.1·.7=.93',['Сравните величину исторического вклада 2.7 и нового −2.'],'Несмотря на отрицательный текущий gradient, v_new остаётся положительной. Momentum не равен текущему gradient и не гарантирует монотонную loss.',momentumCode,[fixture({theta:1,velocity:3,grad:-2,eta:0.1,beta:0.9},[0.93,0.7]),fixture({theta:1,velocity:3,grad:-2,eta:0.1,beta:0},[1.2,-2])],quiz('Что происходит с velocity при beta=0?',['Сохраняется старая','Равна текущему grad','Всегда 0','Равна eta'],1,'v_new=0·v+grad.')),
  ]},
];

const mseGradCode = samples('def mse_gradient(predictions: list[float], targets: list[float]) -> list[float]','function mseGradient(predictions, targets)','pub fn mse_gradient(predictions: &[f64], targets: &[f64]) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(predictions)<=64 or len(predictions)!=len(targets) or any(not math.isfinite(v) or abs(v)>10000 for v in predictions+targets):\n    raise ValueError("Несовместимые конечные векторы")\nreturn [2*(p-t)/len(predictions) for p,t in zip(predictions,targets)]',
  'if (!Array.isArray(predictions)||!Array.isArray(targets)||!predictions.length||predictions.length>64||predictions.length!==targets.length||[...predictions,...targets].some(v=>typeof v!=="number"||!Number.isFinite(v)||Math.abs(v)>10000))throw new RangeError("Несовместимые векторы");\nreturn predictions.map((p,i)=>2*(p-targets[i])/predictions.length);',
  'if predictions.is_empty()||predictions.len()>64||predictions.len()!=targets.len()||predictions.iter().chain(targets).any(|v|!v.is_finite()||v.abs()>10000.0){return Err(InputError::InvalidInput);}\nOk(predictions.iter().zip(targets).map(|(p,t)|2.0*(p-t)/predictions.len() as f64).collect())',
]);
const bceGradCode = samples('def bce_gradient(z: float, y: float) -> float','function bceGradient(z, y)','pub fn bce_gradient(z: f64, y: f64) -> Result<f64, InputError>',[
  'if not math.isfinite(z) or abs(z)>10000 or y not in (0,1):\n    raise ValueError("Некорректные logit/label")\ne=math.exp(-abs(z))\np=1/(1+e) if z>=0 else e/(1+e)\nreturn p-y',
  'if(typeof z!=="number"||!Number.isFinite(z)||Math.abs(z)>10000||(y!==0&&y!==1))throw new RangeError("Некорректные logit/label");\nconst e=Math.exp(-Math.abs(z));\nconst p=z>=0?1/(1+e):e/(1+e);\nreturn p-y;',
  'if !z.is_finite()||z.abs()>10000.0||(y!=0.0&&y!=1.0){return Err(InputError::InvalidInput);}\nlet e=(-z.abs()).exp();\nlet p=if z>=0.0{1.0/(1.0+e)}else{e/(1.0+e)};\nOk(p-y)',
]);
const basicsB: Record<string,PracticeExercise> = {
  'concept.dot-product':exercise('concept.dot-product','transfer-b','Контроль B · линейность по входу','transfer',`Реализуйте dot и проверьте [2,−3]·[−1,4] и удвоенный вход [4,−6]. Нулевой вектор и общий множитель должны вести себя согласно формуле. ${basicsContract}`,'(αx)·w=α(x·w)',['Масштабируется только x, weights остаются прежними.'],'Ответы −14 и −28: dot линеен по каждому аргументу отдельно.',dotCode,[fixture({x:[2,-3],w:[-1,4]},-14),fixture({x:[4,-6],w:[-1,4]},-28)],quiz('Если удвоить оба вектора, dot изменится в…',['2 раза','4 раза','Не изменится'],1,'Каждое произведение координат получает два множителя 2.')),
  'unit.neuron.affine':exercise('unit.neuron.affine','transfer-b','Контроль B · компенсировать сдвиг входа','transfer',`В scalar affine x=2,w=3,b=1. Измените x на 3 и подберите b так, чтобы z сохранился. Напишите ту же векторную affine, проверяя shape. ${basicsContract}`,'b_new=b−w·Δx',['При Δx=1 weighted sum увеличивается на 3.'],'Исходный z=7. Новый b=−2 компенсирует +3 в weighted sum, z остаётся 7.',affineCode,[fixture({x:[2],w:[3],b:1},7),fixture({x:[3],w:[3],b:-2},7)],quiz('x увеличился на 1, w=3. Как меняется b для сохранения z?',['b+3','b−3','b/3'],1,'Сдвиг bias должен компенсировать рост wx на 3.')),
  'unit.neuron.activation.relu':exercise('unit.neuron.activation.relu','transfer-b','Контроль B · convention в нуле','transfer','Напишите relu_and_grad для z=0 и малых значений ±1e−6. Сравните выбранную convention derivative=0 в нуле с центральной разностью. Не выдавайте центральный наклон .5 за обычную derivative.','g(z)=1 для z>0; g(0)=0 по convention',['Справа наклон 1, слева 0.'],'При ±1e−6 derivatives 1 и 0; в 0 обычного единого наклона нет.',reluCode,[fixture({z:0.000001},[0.000001,1]),fixture({z:-0.000001},[0,0])],quiz('Центральная разность ReLU в 0 равна .5. Это означает…',['Обычная derivative=.5','У функции излом; это усреднение двух сторон','Нужен меньший h'],1,'Несовпадение односторонних наклонов не исчезает при уменьшении h.')),
  'unit.neuron.dense':exercise('unit.neuron.dense','transfer-b','Контроль B · новое число output features','transfer',`Напишите dense_batch для B=1,I=3,O=2 с отрицательными weights. Bias добавьте к каждому output. Возвращайте B×O, даже если B=1. ${basicsContract}`,'Y=XWᵀ+b',['Не удаляйте batch dimension для единственного примера.'],'[2,−1,3]·[1,0,−1]+2=1; второй output [−1,2,1] даёт −1, с bias −1 получаем −2.',denseCode,[fixture({x:[[2,-1,3]],w:[[1,0,-1],[-1,2,1]],b:[2,-1]},[[1,-2]])],quiz('При B=1,O=2 результат должен иметь форму…',['[y₀,y₁] без batch','[[y₀,y₁]]','2×2'],1,'Batch остаётся отдельной осью даже при единственном примере.')),
  'unit.loss.mse':exercise('unit.loss.mse','transfer-b','Контроль B · derivative mean, не sum','transfer',`Реализуйте mse_gradient отдельно от mse_loss. Верните вектор ∂MSE/∂predictions. Для n=2 используется коэффициент 2/n=1. ${basicsContract}`,'∂MSE/∂pᵢ=2(pᵢ−tᵢ)/n',['Делитель n нужен и в gradient, не только в loss.'],'Для p=[1,3],t=[0,1] gradient=[1,2]. У одного p=2,t=−1 gradient=6.',mseGradCode,[fixture({predictions:[1,3],targets:[0,1]},[1,2]),fixture({predictions:[2],targets:[-1]},[6])],quiz('При дублировании пакета derivative по каждой отдельной копии pᵢ…',['Удваивается','Делится на 2','Не меняется'],1,'Каждая координата делится на новое удвоенное n; сумма вкладов двух одинаковых копий сохраняется.')),
  'unit.loss.bce':exercise('unit.loss.bce','transfer-b','Контроль B · уверенная ошибка и gradient','transfer','Реализуйте bce_gradient из logit, устойчиво вычислив sigmoid. Сравните z=ln3,y=1 с z=1000,y=0. z конечен в ±10000, y∈{0,1}. Не округляйте probability перед вычитанием y.','∂BCE/∂z=σ(z)−y',['Для z<0 используйте exp(z)/(1+exp(z)), для z≥0 — 1/(1+exp(−z)).'],'В первом случае gradient=.75−1=−.25, во втором ≈1. Уверенная ошибка даёт большую loss и gradient, а accuracy не сообщает степень уверенности.',bceGradCode,[fixture({z:Math.log(3),y:1},-0.25),fixture({z:1000,y:0},1),fixture({z:-1000,y:1},-1)],quiz('z=ln3,y=1. Какая derivative по logit?',['−.25','.75','−ln(.75)'],0,'Sigmoid=.75, derivative=.75−1.')),
  'unit.backprop.check':exercise('unit.backprop.check','transfer-b','Контроль B · обнаружить потерянную ветвь','transfer','Сравните central_gradient в x=1,w=2,b=0 с ошибочным backward, где забыто +q в loss derivative. Напишите независимую центральную разность исходной loss. h=1e−5, остальные bounds прежние.','L=(wx+b)²+(wx+b); [dx,dw,db]=[10,5,5]',['Если забыть прямую ветвь, dx станет 8. Проверка должна различить 8 и 10.'],'Численный dx≈10 отличает полный граф от ошибочного gradient 8; сам forward не меняйте под неверный backward.',finiteCode,[fixture({x:1,w:2,b:0,h:0.00001},[10,5,5])],quiz('Ошибочный derivative только квадрата даёт db=4. Каков верный db при q=2?',['4','5','8'],1,'Прямая ветвь добавляет ещё 1.')),
  'unit.optimizer.momentum':exercise('unit.optimizer.momentum','transfer-b','Контроль B · нулевой gradient не останавливает историю','transfer','При theta=1,v=2,g=0,eta=.1,beta=.5 выполните momentum_step. Затем используйте полученную velocity во втором шаге с g=0. Scalar bounds и convention v_new=beta*v+g прежние.','v_new=βv при g=0',['Нулевой текущий gradient не стирает накопленную velocity.'],'Первый шаг [.9,1], второй [.85,.5]. История затухает геометрически.',momentumCode,[fixture({theta:1,velocity:2,grad:0,eta:0.1,beta:0.5},[0.9,1]),fixture({theta:0.9,velocity:1,grad:0,eta:0.1,beta:0.5},[0.85,0.5])],quiz('При g=0 и beta=.5 velocity после двух шагов равна…',['0','v/2','v/4'],2,'Два множителя .5 дают .25v.')),
};
for (const topic of foundations) topic.exercises.push(basicsB[topic.id]);

const activationCode=samples('def activation_and_grad(z: float, kind: str) -> list[float]','function activationAndGrad(z, kind)','pub fn activation_and_grad(z: f64, kind: &str) -> Result<Vec<f64>, InputError>',[
  'if not math.isfinite(z) or abs(z)>10000 or kind not in ("relu","sigmoid","tanh"):\n    raise ValueError("Некорректная activation")\nif kind=="relu":\n    return [max(0.0,z),1.0 if z>0 else 0.0]\nif kind=="tanh":\n    a=math.tanh(z)\n    return [a,1-a*a]\ne=math.exp(-abs(z))\na=1/(1+e) if z>=0 else e/(1+e)\nreturn [a,a*(1-a)]',
  'if(typeof z!=="number"||!Number.isFinite(z)||Math.abs(z)>10000||!["relu","sigmoid","tanh"].includes(kind))throw new RangeError("Некорректная activation");\nif(kind==="relu")return [Math.max(0,z),z>0?1:0];\nif(kind==="tanh"){const a=Math.tanh(z);return [a,1-a*a];}\nconst e=Math.exp(-Math.abs(z)),a=z>=0?1/(1+e):e/(1+e);\nreturn [a,a*(1-a)];',
  'if !z.is_finite()||z.abs()>10000.0{return Err(InputError::InvalidInput);}\nlet (a,g)=match kind{"relu"=>(z.max(0.0),if z>0.0{1.0}else{0.0}),"tanh"=>{let a=z.tanh();(a,1.0-a*a)},"sigmoid"=>{let e=(-z.abs()).exp();let a=if z>=0.0{1.0/(1.0+e)}else{e/(1.0+e)};(a,a*(1.0-a))},_=>return Err(InputError::InvalidInput)};\nOk(vec![a,g])',
]);
const adamCode=samples('def adam_step(theta: float, m: float, v: float, grad: float, eta: float, beta1: float, beta2: float, t: int, eps: float) -> list[float]','function adamStep(theta, m, v, grad, eta, beta1, beta2, t, eps)','pub fn adam_step(theta: f64, m: f64, v: f64, grad: f64, eta: f64, beta1: f64, beta2: f64, t: u32, eps: f64) -> Result<Vec<f64>, InputError>',[
  'if any(not math.isfinite(a) or abs(a)>10000 for a in (theta,m,grad)) or not math.isfinite(v) or not 0<=v<=1e8 or not math.isfinite(eta) or not 0<=eta<=1 or any(not math.isfinite(a) or not 0<=a<1 for a in (beta1,beta2)) or not isinstance(t,int) or not 1<=t<=1000000 or not math.isfinite(eps) or not 1e-12<=eps<=1:\n    raise ValueError("Некорректный Adam state")\nm_new=beta1*m+(1-beta1)*grad\nv_new=beta2*v+(1-beta2)*grad*grad\nm_hat=m_new/(1-beta1**t)\nv_hat=v_new/(1-beta2**t)\nreturn [theta-eta*m_hat/(math.sqrt(v_hat)+eps),m_new,v_new]',
  'if([theta,m,grad].some(a=>typeof a!=="number"||!Number.isFinite(a)||Math.abs(a)>10000)||!Number.isFinite(v)||v<0||v>1e8||!Number.isFinite(eta)||eta<0||eta>1||[beta1,beta2].some(a=>!Number.isFinite(a)||a<0||a>=1)||!Number.isInteger(t)||t<1||t>1e6||!Number.isFinite(eps)||eps<1e-12||eps>1)throw new RangeError("Некорректный Adam state");\nconst mNew=beta1*m+(1-beta1)*grad,vNew=beta2*v+(1-beta2)*grad*grad;\nconst mHat=mNew/(1-beta1**t),vHat=vNew/(1-beta2**t);\nreturn [theta-eta*mHat/(Math.sqrt(vHat)+eps),mNew,vNew];',
  'if [theta,m,grad].iter().any(|a|!a.is_finite()||a.abs()>10000.0)||!v.is_finite()||!(0.0..=1e8).contains(&v)||!eta.is_finite()||!(0.0..=1.0).contains(&eta)||[beta1,beta2].iter().any(|a|!a.is_finite()||!(0.0..1.0).contains(a))||t==0||t>1000000||!eps.is_finite()||!(1e-12..=1.0).contains(&eps){return Err(InputError::InvalidInput);}\nlet m_new=beta1*m+(1.0-beta1)*grad;\nlet v_new=beta2*v+(1.0-beta2)*grad*grad;\nlet m_hat=m_new/(1.0-beta1.powi(t as i32));\nlet v_hat=v_new/(1.0-beta2.powi(t as i32));\nOk(vec![theta-eta*m_hat/(v_hat.sqrt()+eps),m_new,v_new])',
]);
type LessonRows = [string,string,string,string,string[],PracticeExercise['fixtures'],PracticeExercise['quiz'],Samples?];
function triple(id:string,lessonId:string,title:string,sourceSection:string,prerequisites:string[],code:Samples,rows:[LessonRows,LessonRows,LessonRows]):PracticeTopic {
  return {id,lessonId,title,sourceSection,prerequisites,exercises:rows.map((row,i)=>exercise(id,['guided','transfer-a','transfer-b'][i],row[0],i?'transfer':'guided',row[1],row[2],row[4],row[3],row[7]||code,row[5],row[6]))};
}
const adamInput={theta:1,m:0,v:0,grad:2,eta:.1,beta1:.9,beta2:.999,t:1,eps:.1};
const extraFoundations:PracticeTopic[]=[
  triple('unit.neuron.activation','neuron','ReLU, sigmoid и tanh','neuron-activation',['concept.derivative'],activationCode,[
    ['Три функции и их локальные derivatives','Реализуйте activation_and_grad(z,kind) → [value,derivative] для relu/sigmoid/tanh. z конечен в ±10000, неизвестный kind — ошибка. У ReLU в 0 convention=0; sigmoid вычисляйте без exp(10000).','ReLU=max(0,z); σ′=σ(1−σ); tanh′=1−tanh²','При z=0 sigmoid=.5, derivative=.25; tanh=0, derivative=1; ReLU value=0, convention derivative=0.',['Обратите внимание на разные derivatives в одной и той же точке 0.'],[fixture({z:0,kind:'sigmoid'},[.5,.25]),fixture({z:0,kind:'tanh'},[0,1]),fixture({z:0,kind:'relu'},[0,0])],quiz('Где локальный наклон при z=0 равен 1?',['sigmoid','tanh','ReLU по convention 0'],1,'tanh′(0)=1−0²=1.')],
    ['Контроль A · sigmoid и насыщение','Реализуйте ту же activation_and_grad и сравните sigmoid в ln3, −ln3 и 1000. Контракт прежний. Большая уверенность означает малый локальный derivative, а не большое значение derivative.','σ(ln3)=3/4; σ′=3/16','Значения .75/.25 дают одинаковую derivative .1875. При 1000 value≈1 и derivative≈0.',['Используйте sigmoid symmetry σ(−z)=1−σ(z).'],[fixture({z:Math.log(3),kind:'sigmoid'},[.75,.1875]),fixture({z:-Math.log(3),kind:'sigmoid'},[.25,.1875]),fixture({z:1000,kind:'sigmoid'},[1,0])],quiz('При sigmoid saturation derivative приближается к…',['1','0','1000'],1,'σ(1−σ) мала у обоих краёв распределения.')],
    ['Контроль B · tanh и масштаб gradient','Реализуйте ту же activation_and_grad и сравните tanh(ln3/2) с tanh(1000). Входные bounds прежние. Объясните различие ReLU: положительные большие значения у неё не насыщаются.','tanh(ln3/2)=1/2; derivative=3/4','При tanh=±1 локальный derivative≈0. У ReLU на положительной ветви derivative=1 даже для z=1000.',['В tanh derivative используется квадрат value.'],[fixture({z:Math.log(3)/2,kind:'tanh'},[.5,.75]),fixture({z:1000,kind:'tanh'},[1,0]),fixture({z:1000,kind:'relu'},[1000,1])],quiz('Какая из этих функций сохраняет derivative=1 при z=1000?',['tanh','sigmoid','ReLU'],2,'ReLU на положительной стороне линейна.')],
  ]),
  triple('unit.optimizer.adam','optimizers','Adam: моменты и bias correction','Adam method',['unit.optimizer.momentum'],adamCode,[
    ['Первый шаг с нулевой историей','Напишите scalar adam_step → [theta_new,m_new,v_new]. eta∈[0,1], beta1,beta2∈[0,1), integer t∈[1,10⁶], eps∈[1e−12,1], theta,m,g конечны в ±10000, v∈[0,10⁸]. t уже номер нового шага, начиная с 1; неверный state — ошибка.','m=β₁m_old+(1−β₁)g; v=β₂v_old+(1−β₂)g²; m̂=m/(1−β₁ᵗ); v̂=v/(1−β₂ᵗ); θ_new=θ−ηm̂/(√v̂+eps)','Для g=2 в первом шаге m=.2,v=.004; correction даёт m_hat=2,v_hat=4. При eps=.1 update=.1·2/2.1.',['Bias correction нужна и для m, и для v.'],[fixture(adamInput,[1-.2/2.1,.2,.004])],quiz('Чему равен m_hat первого шага с m_old=0,g=2,beta1=.9?',['.2','2','20'],1,'m_new=.2, деление на 1−.9 даёт 2.')],
    ['Контроль A · передать ненулевую историю','После первого шага возьмите theta=1−.2/2.1,m=.2,v=.004,t=2,grad=−2. Реализуйте scalar adam_step с прежними bounds. Историю не сбрасывайте; коррекция степени использует t=2.','m_new=.9·.2+.1·(−2)=−.02; v_new=.999·.004+.001·4=.007996','m_hat=−.02/.19, v_hat=4. Новый шаг положителен, но существенно меньше первого из-за накопленной истории.',['Перенесите оба момента, не только m.'],[fixture({...adamInput,theta:1-.2/2.1,m:.2,v:.004,grad:-2,t:2},[1-.2/2.1+.1*(.02/.19)/2.1,-.02,.007996])],quiz('Если сбросить m/v перед вторым шагом, что потеряется?',['Только precision','История gradients','Количество параметров'],1,'Adam использует накопленные первые и вторые моменты.')],
    ['Контроль B · epsilon нарушает точную scale symmetry','Сравните первый Adam шаг при grad=2 и grad=20, eps=.1, прочие inputs прежние. Реализуйте ту же функцию. Не утверждайте, что масштаб gradient всегда полностью сокращается при eps>0.','g/(|g|+eps) ≠ 10g/(10|g|+eps) при eps>0','Новые theta: 1−.2/2.1 и 1−2/20.1. Без epsilon величины были бы равны для положительных g; с epsilon отличаются.',['epsilon прибавляется после sqrt, а не под корень.'],[fixture({...adamInput,grad:20},[1-2/20.1,2,.4])],quiz('Почему два шага при gradients 2 и 20 слегка отличаются?',['Из-за ненулевого epsilon','Adam всегда умножает шаг на grad','t изменился'],0,'epsilon не масштабируется вместе с gradient.')],
  ]),
];

const standardizeCode=samples('def standardize(train: list[float], heldout: list[float]) -> dict[str, object]','function standardize(train, heldout)','pub fn standardize(train: &[f64], heldout: &[f64]) -> Result<Standardized, InputError>',[
  'if not 1<=len(train)<=64 or len(heldout)>64 or any(not math.isfinite(a) or abs(a)>10000 for a in train+heldout):\n    raise ValueError("Неверные данные")\nmean=sum(train)/len(train)\nvariance=sum((a-mean)**2 for a in train)/len(train)\nscale=math.sqrt(variance) if variance>0 else 1.0\nreturn {"mean":mean,"scale":scale,"values":[(a-mean)/scale for a in heldout]}',
  'if(!Array.isArray(train)||!Array.isArray(heldout)||!train.length||train.length>64||heldout.length>64||[...train,...heldout].some(a=>typeof a!=="number"||!Number.isFinite(a)||Math.abs(a)>10000))throw new RangeError("Неверные данные");\nconst mean=train.reduce((s,a)=>s+a,0)/train.length;\nconst variance=train.reduce((s,a)=>s+(a-mean)**2,0)/train.length;\nconst scale=variance>0?Math.sqrt(variance):1;\nreturn {mean,scale,values:heldout.map(a=>(a-mean)/scale)};',
  'if train.is_empty()||train.len()>64||heldout.len()>64||train.iter().chain(heldout).any(|a|!a.is_finite()||a.abs()>10000.0){return Err(InputError::InvalidInput);}\nlet mean=train.iter().sum::<f64>()/train.len() as f64;\nlet variance=train.iter().map(|a|(a-mean).powi(2)).sum::<f64>()/train.len() as f64;\nlet scale=if variance>0.0{variance.sqrt()}else{1.0};\nOk(Standardized{mean,scale,values:heldout.iter().map(|a|(a-mean)/scale).collect()})',
],'pub struct Standardized { pub mean:f64, pub scale:f64, pub values:Vec<f64> }\n');
const groupCode=samples('def group_membership(groups: list[int], train_groups: list[int]) -> list[int]','function groupMembership(groups, trainGroups)','pub fn group_membership(groups: &[usize], train_groups: &[usize]) -> Result<Vec<f64>, InputError>',[
  'if len(groups)>64 or len(train_groups)>64 or any(not isinstance(g,int) or g<0 or g>1000000 for g in groups+train_groups):\n    raise ValueError("Неверные group IDs")\nselected=set(train_groups)\nreturn [1 if g in selected else 0 for g in groups]',
  'if(!Array.isArray(groups)||!Array.isArray(trainGroups)||groups.length>64||trainGroups.length>64||[...groups,...trainGroups].some(g=>!Number.isInteger(g)||g<0||g>1e6))throw new RangeError("Неверные group IDs");\nconst selected=new Set(trainGroups);\nreturn groups.map(g=>selected.has(g)?1:0);',
  'if groups.len()>64||train_groups.len()>64||groups.iter().chain(train_groups).any(|g|*g>1000000){return Err(InputError::InvalidInput);}\nOk(groups.iter().map(|g|if train_groups.contains(g){1.0}else{0.0}).collect())',
]);
const batchCode=samples('def train_batch(theta: list[float], x: list[float], y: list[float], eta: float, l2: float) -> list[float]','function trainBatch(theta, x, y, eta, l2)','pub fn train_batch(theta: &[f64], x: &[f64], y: &[f64], eta: f64, l2: f64) -> Result<Vec<f64>, InputError>',[
  'if len(theta)!=2 or not 1<=len(x)<=64 or len(x)!=len(y) or any(not math.isfinite(a) or abs(a)>100 for a in theta+x) or any(a not in (0,1) for a in y) or not math.isfinite(eta) or not 0<=eta<=1 or not math.isfinite(l2) or not 0<=l2<=1:\n    raise ValueError("Неверный batch/state")\ngw=gb=0.0\nfor a,label in zip(x,y):\n    z=theta[0]*a+theta[1]\n    e=math.exp(-abs(z)); p=1/(1+e) if z>=0 else e/(1+e)\n    gw+=(p-label)*a/len(x); gb+=(p-label)/len(x)\ngw+=l2*theta[0]\nreturn [theta[0]-eta*gw,theta[1]-eta*gb]',
  'if(!Array.isArray(theta)||theta.length!==2||!Array.isArray(x)||!Array.isArray(y)||!x.length||x.length>64||x.length!==y.length||[...theta,...x].some(a=>!Number.isFinite(a)||Math.abs(a)>100)||y.some(a=>a!==0&&a!==1)||!Number.isFinite(eta)||eta<0||eta>1||!Number.isFinite(l2)||l2<0||l2>1)throw new RangeError("Неверный batch/state");\nlet gw=0,gb=0;\nfor(let i=0;i<x.length;i++){const z=theta[0]*x[i]+theta[1],e=Math.exp(-Math.abs(z)),p=z>=0?1/(1+e):e/(1+e);gw+=(p-y[i])*x[i]/x.length;gb+=(p-y[i])/x.length;}\ngw+=l2*theta[0];\nreturn [theta[0]-eta*gw,theta[1]-eta*gb];',
  'if theta.len()!=2||x.is_empty()||x.len()>64||x.len()!=y.len()||theta.iter().chain(x).any(|a|!a.is_finite()||a.abs()>100.0)||y.iter().any(|a|*a!=0.0&&*a!=1.0)||!eta.is_finite()||!(0.0..=1.0).contains(&eta)||!l2.is_finite()||!(0.0..=1.0).contains(&l2){return Err(InputError::InvalidInput);}\nlet(mut gw,mut gb)=(0.0,0.0);\nfor(a,label)in x.iter().zip(y){let z=theta[0]*a+theta[1];let e=(-z.abs()).exp();let p=if z>=0.0{1.0/(1.0+e)}else{e/(1.0+e)};gw+=(p-label)*a/x.len() as f64;gb+=(p-label)/x.len() as f64;}\ngw+=l2*theta[0];\nOk(vec![theta[0]-eta*gw,theta[1]-eta*gb])',
]);
const hiddenCode=samples('def hidden_features(points: list[list[float]], weights: list[float], bias: float) -> list[float]','function hiddenFeatures(points, weights, bias)','pub fn hidden_features(points: &[Vec<f64>], weights: &[f64], bias: f64) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(points)<=64 or not 1<=len(weights)<=64 or any(len(p)!=len(weights) for p in points) or any(not math.isfinite(a) or abs(a)>100 for p in points+[weights,[bias]] for a in p):\n    raise ValueError("Неверные features")\nreturn [math.tanh(sum(a*w for a,w in zip(p,weights))+bias) for p in points]',
  'if(!Array.isArray(points)||!Array.isArray(weights)||!points.length||points.length>64||!weights.length||weights.length>64||points.some(p=>!Array.isArray(p)||p.length!==weights.length)||[...points.flat(),...weights,bias].some(a=>!Number.isFinite(a)||Math.abs(a)>100))throw new RangeError("Неверные features");\nreturn points.map(p=>Math.tanh(p.reduce((s,a,i)=>s+a*weights[i],bias)));',
  'if points.is_empty()||points.len()>64||weights.is_empty()||weights.len()>64||points.iter().any(|p|p.len()!=weights.len())||points.iter().flatten().chain(weights).chain(std::iter::once(&bias)).any(|a|!a.is_finite()||a.abs()>100.0){return Err(InputError::InvalidInput);}\nOk(points.iter().map(|p|(p.iter().zip(weights).map(|(a,w)|a*w).sum::<f64>()+bias).tanh()).collect())',
]);
const confusionCode=samples('def confusion_matrix(p: list[float], y: list[float], threshold: float) -> list[float]','function confusionMatrix(p, y, threshold)','pub fn confusion_matrix(p: &[f64], y: &[f64], threshold: f64) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(p)<=64 or len(p)!=len(y) or any(not math.isfinite(a) or not 0<=a<=1 for a in p+[threshold]) or any(a not in (0,1) for a in y):\n    raise ValueError("Неверные probabilities/labels")\ntp=fp=fn=tn=0\nfor a,label in zip(p,y):\n    positive=a>=threshold\n    if positive and label==1: tp+=1\n    elif positive: fp+=1\n    elif label==1: fn+=1\n    else: tn+=1\nreturn [tp,fp,fn,tn]',
  'if(!Array.isArray(p)||!Array.isArray(y)||!p.length||p.length>64||p.length!==y.length||[...p,threshold].some(a=>!Number.isFinite(a)||a<0||a>1)||y.some(a=>a!==0&&a!==1))throw new RangeError("Неверные probabilities/labels");\nconst counts=[0,0,0,0];\np.forEach((a,i)=>counts[a>=threshold?(y[i]===1?0:1):(y[i]===1?2:3)]++);\nreturn counts;',
  'if p.is_empty()||p.len()>64||p.len()!=y.len()||p.iter().chain(std::iter::once(&threshold)).any(|a|!a.is_finite()||!(0.0..=1.0).contains(a))||y.iter().any(|a|*a!=0.0&&*a!=1.0){return Err(InputError::InvalidInput);}\nlet mut counts=vec![0.0;4];\nfor(a,label)in p.iter().zip(y){let i=if *a>=threshold{if *label==1.0{0}else{1}}else if *label==1.0{2}else{3};counts[i]+=1.0;}\nOk(counts)',
]);
const xorCode=samples('def xor_example(params: list[float], xy: list[float], target: float) -> list[float]','function xorExample(params, xy, target)','pub fn xor_example(params: &[f64], xy: &[f64], target: f64) -> Result<Vec<f64>, InputError>',[
  'if len(params)!=17 or len(xy)!=2 or target not in (0,1) or any(not math.isfinite(a) or abs(a)>10 for a in params+xy):\n    raise ValueError("Нужны 17 params, 2 inputs, binary target")\nh=[math.tanh(params[2*j]*xy[0]+params[2*j+1]*xy[1]+params[8+j]) for j in range(4)]\nz=sum(params[12+j]*h[j] for j in range(4))+params[16]\ne=math.exp(-abs(z)); p=1/(1+e) if z>=0 else e/(1+e)\nloss=max(z,0)-z*target+math.log1p(e)\ndz=p-target\ng=[0.0]*17\nfor j in range(4):\n    dh=dz*params[12+j]*(1-h[j]*h[j])\n    g[2*j]=dh*xy[0];g[2*j+1]=dh*xy[1];g[8+j]=dh;g[12+j]=dz*h[j]\ng[16]=dz\nreturn [loss]+g',
  'if(!Array.isArray(params)||!Array.isArray(xy)||params.length!==17||xy.length!==2||(target!==0&&target!==1)||[...params,...xy].some(a=>!Number.isFinite(a)||Math.abs(a)>10))throw new RangeError("Неверный XOR example");\nconst h=Array.from({length:4},(_,j)=>Math.tanh(params[2*j]*xy[0]+params[2*j+1]*xy[1]+params[8+j]));\nconst z=h.reduce((s,a,j)=>s+params[12+j]*a,params[16]),e=Math.exp(-Math.abs(z)),p=z>=0?1/(1+e):e/(1+e);\nconst loss=Math.max(z,0)-z*target+Math.log1p(e),dz=p-target,g=Array(17).fill(0);\nfor(let j=0;j<4;j++){const dh=dz*params[12+j]*(1-h[j]*h[j]);g[2*j]=dh*xy[0];g[2*j+1]=dh*xy[1];g[8+j]=dh;g[12+j]=dz*h[j];}\ng[16]=dz;\nreturn [loss,...g];',
  'if params.len()!=17||xy.len()!=2||(target!=0.0&&target!=1.0)||params.iter().chain(xy).any(|a|!a.is_finite()||a.abs()>10.0){return Err(InputError::InvalidInput);}\nlet h:Vec<f64>=(0..4).map(|j|(params[2*j]*xy[0]+params[2*j+1]*xy[1]+params[8+j]).tanh()).collect();\nlet z=h.iter().enumerate().map(|(j,a)|params[12+j]*a).sum::<f64>()+params[16];\nlet e=(-z.abs()).exp();let p=if z>=0.0{1.0/(1.0+e)}else{e/(1.0+e)};\nlet loss=z.max(0.0)-z*target+e.ln_1p();let dz=p-target;let mut g=vec![0.0;17];\nfor j in 0..4{let dh=dz*params[12+j]*(1.0-h[j]*h[j]);g[2*j]=dh*xy[0];g[2*j+1]=dh*xy[1];g[8+j]=dh;g[12+j]=dz*h[j];}\ng[16]=dz;let mut result=vec![loss];result.extend(g);Ok(result)',
]);
const zero17=Array(17).fill(0);
const sparse17=zero17.map((_,i)=>i===0?1:i===12?2:0);
const xorH=Math.tanh(1),xorZ=2*xorH,xorDz=1/(1+Math.exp(-xorZ))-1;
const sparseGradient=zero17.map((_,i)=>i===0||i===8?xorDz*2*(1-xorH*xorH):i===12?xorDz*xorH:i===16?xorDz:0);
const networkTopics:PracticeTopic[]=[
  triple('unit.network.split','network','Train-only statistics и group split','train validation panels',['concept.expectation','concept.variance'],standardizeCode,[
    ['Fit на train, transform на held-out','Реализуйте standardize(train,heldout) → {mean,scale,values}. Train непустой, оба массива до 64 finite значений ±10000. Population variance делится на n, при нулевой variance scale=1. Held-out не участвует в fit; неверные данные — ошибка.','μ=mean(train); s=√mean((train−μ)²); transform=(x−μ)/s','Train [1,3] задаёт μ=2,s=1; held-out [2,4] → [0,2].',['Функция fit видит только train.'],[fixture({train:[1,3],heldout:[2,4]},{mean:2,scale:1,values:[0,2]}),fixture({train:[5,5],heldout:[5,7]},{mean:5,scale:1,values:[0,2]})],quiz('Можно ли включить validation в mean для normalizer перед оценкой?',['Да, это точнее','Нет: это утечка evaluation data','Только если labels не используются'],1,'Даже без labels fitted statistics получают сведения из held-out.')],
    ['Контроль A · выброс validation','Измените только held-out [2,4] на [2,1000]. Реализуйте standardize с прежним контрактом: mean/scale должны остаться train-only. Не скрывайте выброс пересчётом fitted statistics.','fit(train) не зависит от heldout','μ=2,s=1 остаются прежними, transformed outlier=998.',['Сравните state в обеих fixtures.'],[fixture({train:[1,3],heldout:[2,1000]},{mean:2,scale:1,values:[0,998]})],quiz('Что может измениться от нового held-out выброса?',['Fitted mean','Fitted scale','Только transformed held-out'],2,'Transform применяет уже fitted state.')],
    ['Контроль B · держать группу в одном split','Напишите group_membership(groups,train_groups) → flags 1=train/0=heldout. IDs integer от 0 до 10⁶, массивы до 64. Каждый повтор одного group ID должен попасть в один split, независимо от позиции строки.','split(row)=membership(group_id,train_group_ids)','Для groups [7,2,7,3] и train_groups [7] flags [1,0,1,0]. Это предотвращает утечку дубликатов одной группы между train и held-out.',['Выбирайте membership по ID, а не по индексу строки.'],[fixture({groups:[7,2,7,3],train_groups:[7]},[1,0,1,0])],quiz('Два снимка одного пациента нужно делить…',['Случайно по строкам','По patient/group ID','По ширине изображения'],1,'Group split удерживает связанные наблюдения на одной стороне.'),groupCode],
  ]),
  triple('unit.network.boundary','network','Mini-batch logistic update','boundary-experiment',['unit.loss.bce','unit.optimizer.sgd'],batchCode,[
    ['Средний gradient и L2 только weight','Напишите train_batch для scalar logistic z=w*x+b и theta=[w,b]. Верните new theta; eta,l2∈[0,1], batch 1–64, labels 0/1, finite theta/x в ±100. L2 loss=(l2/2)*w², bias не regularize. Неверные формы — ошибка.','gw=mean((σ(z)−y)x)+l2·w; gb=mean(σ(z)−y)','При theta=0,batch x=[−1,1],y=[0,1] gradient w=−.5,b=0; eta=.2 даёт [.1,0].',['Не обновляйте params внутри цикла отдельных samples.'],[fixture({theta:[0,0],x:[-1,1],y:[0,1],eta:.2,l2:0},[.1,0]),fixture({theta:[2,3],x:[1],y:[1],eta:0,l2:.5},[2,3])],quiz('Почему обновление делается после усреднения batch?',['Все gradients должны считаться при одних params','Чтобы потерять порядок','Для увеличения n'],0,'Иначе это последовательность online шагов, зависящая от порядка.')],
    ['Контроль A · переставить batch','Реализуйте ту же train_batch и поменяйте порядок двух samples местами. Вся формула и bounds прежние. Итог full-batch update должен сохраниться.','mean(Pg)=mean(g)','Для x=[1,−1],y=[1,0],theta=0 снова получится [.1,0].',['Weights фиксируются на всё вычисление gradient.'],[fixture({theta:[0,0],x:[1,-1],y:[1,0],eta:.2,l2:0},[.1,0])],quiz('Перестановка полного batch при фиксированных params меняет mean gradient?',['Да','Нет','Только для n=2'],1,'Сумма одинаковых вкладов не зависит от порядка, кроме малой roundoff погрешности.')],
    ['Контроль B · отделить L2 от bias','Возьмите theta=[2,−2],x=[1],y=[0],eta=.1,l2=.5. Реализуйте train_batch. Здесь z=0: sigmoid=.5. L2 добавьте только к gw, не к gb.','gw=.5+.5·2=1.5; gb=.5','Новые theta [1.85,−2.05]. Regularizing bias было бы иной loss convention.',['Посчитайте data и penalty вклады отдельно.'],[fixture({theta:[2,-2],x:[1],y:[0],eta:.1,l2:.5},[1.85,-2.05])],quiz('Какой L2 вклад приходит в gradient bias по данному контракту?',['l2*b','0','l2*w'],1,'Penalty зависит только от w.')],
  ]),
  triple('unit.network.representations','network','Скрытый feature — вычисленный признак','network-representations',['unit.neuron.dense','unit.neuron.activation'],hiddenCode,[
    ['Один hidden feature на несколько points','Напишите hidden_features(points,weights,bias): для каждой точки верните один tanh feature. Число points и feature-width 1–64, одинаковые формы; finite values в ±100. Это координата representation, не физическая xyz.','h=tanh(w·x+b)','Для weights=[1,−1],bias=0 точки [0,0] и [1,1] имеют одинаковый h=0, хотя исходные x различны.',['Каждая точка вычисляется отдельно.'],[fixture({points:[[0,0],[1,1]],weights:[1,-1],bias:0},[0,0])],quiz('Одинаковый hidden feature означает одинаковые исходные inputs?',['Да','Нет: отображение может сжимать различия','Только если tanh'],1,'Многие inputs могут отображаться в одну representation.')],
    ['Контроль A · saturation скрывает расстояние','Реализуйте hidden_features и сравните points [10] и [20] при w=1,b=0. Оба features близки к 1; исходное расстояние 10 не сохраняется. Bounds прежние.','h=tanh(x)','Скрытые values почти совпадают: tanh10≈.99999999588,tanh20≈1. Representation не обязана сохранять исходные расстояния.',['tanh насыщается при больших аргументах.'],[fixture({points:[[10],[20]],weights:[1],bias:0},[Math.tanh(10),Math.tanh(20)])],quiz('Разность tanh(20)−tanh(10) примерно…',['10','1','Почти 0'],2,'Оба аргумента в области saturation.')],
    ['Контроль B · смена signs features','Замените weights=[1] на [−1], bias=0, points=[[-1],[1]]. Напишите hidden_features; tanh odd, поэтому signs должны поменяться. Это не смена физической оси и не изменение labels.','tanh(−z)=−tanh(z)','Ответ [tanh1,−tanh1]. Output head мог бы компенсировать смену знака своим weight и сохранить predictions.',['Сравните с weights=[1], не сортируйте outputs.'],[fixture({points:[[-1],[1]],weights:[-1],bias:0},[Math.tanh(1),-Math.tanh(1)])],quiz('Если h→−h и output weight a→−a, logit a*h…',['Сменит знак','Сохранится','Станет 0'],1,'Два минуса сокращаются.')],
  ]),
  triple('unit.network.xor','network','XOR: один example, 17 params','network-xor',['unit.loss.bce','unit.backprop.shared'],xorCode,[
    ['Forward и локальный backward одного example','Напишите xor_example(params,xy,target) → [loss,...17 gradients] для 2→4 tanh→1 logit. Порядок: 8 weights hidden row-major, 4 hidden biases, 4 output weights, output bias. Конечные params/xy в ±10, длины17/2, label0/1. Это один example; mean batch gradient получаем усреднением.','hⱼ=tanh(Wⱼx+bⱼ); z=Σaⱼhⱼ+c; dz=σ(z)−y; dhⱼ=dz·aⱼ(1−hⱼ²)','При params=0 loss=ln2, hidden gradients=0, output weights gradients=0, только output bias gradient=−.5 для y=1.',['Сначала forward, затем цепочка output→hidden→weights.'],[fixture({params:zero17,xy:[1,0],target:1},[Math.LN2,...zero17.slice(0,16),-.5])],quiz('Сколько params у 2→4→1 сети с biases?',['12','16','17'],2,'8+4+4+1=17.')],
    ['Контроль A · не нулевая инициализация','В params положите W₀₀=1,a₀=2, всё остальное 0, xy=[1,0],y=1. Реализуйте xor_example и проверьте, что gradients приходят в W₀₀,b₀,a₀,c. Bounds и порядок прежние.','dh₀=dz·2·(1−tanh²1)','Ненулевой output weight открывает путь gradient к hidden weight; input x₂=0 оставляет gradient W₀₁ нулевым.',['Нулевой input и нулевой gradient имеют разные причины.'],[fixture({params:sparse17,xy:[1,0],target:1},[Math.log1p(Math.exp(-xorZ)),...sparseGradient])],quiz('Почему gradient W₀₁=0 в этой точке?',['Output weight=0','Вторая координата input=0','tanh derivative=0'],1,'dW₀₁=dh₀*x₂.')],
    ['Контроль B · симметрия нулевой инициализации','Реализуйте xor_example для всех четырёх XOR inputs при params=0. target [0,1,1,0]. Усредните gradients: bias вклады ±.5 взаимно уничтожатся; остальные 0. Объясните, почему один SGD шаг не разрушает симметрию.','mean dz=(.5−0+.5−1+.5−1+.5−0)/4=0','Полный XOR batch при нулевой инициализации даёт нулевой gradient всех17params; сеть не начнёт учиться от этого шага.',['Инициализация нужна для нарушения симметрии hidden units.'],[fixture({params:zero17,xy:[0,0],target:0},[Math.LN2,...zero17.slice(0,16),.5]),fixture({params:zero17,xy:[1,1],target:0},[Math.LN2,...zero17.slice(0,16),.5]),fixture({params:zero17,xy:[0,1],target:1},[Math.LN2,...zero17.slice(0,16),-.5])],quiz('Что даст SGD полного XOR batch при всех params=0?',['Сразу решит XOR','Params останутся 0','Всегда NaN'],1,'Mean gradient в симметричной точке равен 0.')],
  ]),
  triple('unit.network.diagnostics','network','Confusion matrix и threshold','diagnostics panel',['unit.loss.bce'],confusionCode,[
    ['TP,FP,FN,TN с явной границей','Напишите confusion_matrix(p,y,threshold) → [TP,FP,FN,TN]. positive определяется p≥threshold. p и threshold конечны в [0,1], labels 0/1, n1–64; формы совпадают. Неверные inputs — ошибка.','predicted positive ⇔ p≥threshold','Для p=[.9,.7,.4,.1],y=[1,0,1,0],threshold=.5: по одному TP,FP,FN,TN.',['Сначала predicted label, затем сопоставление true label.'],[fixture({p:[.9,.7,.4,.1],y:[1,0,1,0],threshold:.5},[1,1,1,1]),fixture({p:[.5],y:[1],threshold:.5},[1,0,0,0])],quiz('p=.5,threshold=.5 по этому контракту — это…',['Negative','Positive','Ошибка'],1,'Используется ≥, включая равенство.')],
    ['Контроль A · поднять threshold','Для того же p/y поднимите threshold с .5 до .8. Реализуйте confusion_matrix. BCE от probabilities не меняется, но predicted labels и accuracy могут измениться.','threshold меняет pred, не p','Теперь TP=1,FP=0,FN=1,TN=2. Accuracy=3/4 вместо1/2; BCE прежняя.',['Loss не получает threshold как input.'],[fixture({p:[.9,.7,.4,.1],y:[1,0,1,0],threshold:.8},[1,0,1,2])],quiz('Что меняется при сдвиге threshold без переобучения?',['Probabilities','BCE','Confusion matrix'],2,'Predicted labels меняются, сами probabilities остаются.')],
    ['Контроль B · отсутствующий положительный класс','Проверьте confusion_matrix для y=[0,0],p=[.8,.2]. Контракт прежний. Не вычисляйте recall как 0/0: функция возвращает counts, определение undefined ratio оставьте отдельному UI.','TP+FN=0 при отсутствии true positives','Ответ [0,1,0,1]. Recall не определён; автоматически выдавать100% было бы неверно.',['Отделите counts от производных метрик.'],[fixture({p:[.8,.2],y:[0,0],threshold:.5},[0,1,0,1])],quiz('Каков recall, если TP+FN=0?',['100%','0% по математике','Не определён'],2,'Знаменатель равен0; нужна отдельная convention отображения.')],
  ]),
];

const embeddingCode=samples('def embedding_lookup(ids: list[int], table: list[list[float]], positions: list[list[float]]) -> list[list[float]]','function embeddingLookup(ids, table, positions)','pub fn embedding_lookup(ids: &[usize], table: &[Vec<f64>], positions: &[Vec<f64>]) -> Result<Vec<Vec<f64>>, InputError>',[
  'if not 1<=len(ids)<=64 or not 1<=len(table)<=64 or not table[0] or len(table[0])>64 or len(positions)!=len(ids) or any(not isinstance(i,int) or i<0 or i>=len(table) for i in ids):\n    raise ValueError("Неверные ids/table/positions")\nd=len(table[0])\nif any(len(row)!=d for row in table+positions) or any(not math.isfinite(a) or abs(a)>10000 for row in table+positions for a in row):\n    raise ValueError("Неверная ширина/значения")\nreturn [[a+b for a,b in zip(table[i],pos)] for i,pos in zip(ids,positions)]',
  'if(!Array.isArray(ids)||!Array.isArray(table)||!Array.isArray(positions)||!ids.length||ids.length>64||!table.length||table.length>64||!Array.isArray(table[0])||!table[0].length||table[0].length>64||positions.length!==ids.length||ids.some(i=>!Number.isInteger(i)||i<0||i>=table.length))throw new RangeError("Неверные ids/table/positions");\nconst d=table[0].length;if([...table,...positions].some(row=>!Array.isArray(row)||row.length!==d)||[...table.flat(),...positions.flat()].some(a=>!Number.isFinite(a)||Math.abs(a)>10000))throw new RangeError("Неверная ширина/значения");\nreturn ids.map((id,j)=>table[id].map((a,i)=>a+positions[j][i]));',
  'if ids.is_empty()||ids.len()>64||table.is_empty()||table.len()>64||table[0].is_empty()||table[0].len()>64||positions.len()!=ids.len()||ids.iter().any(|i|*i>=table.len()){return Err(InputError::InvalidInput);}\nlet d=table[0].len();if table.iter().chain(positions).any(|row|row.len()!=d)||table.iter().chain(positions).flatten().any(|a|!a.is_finite()||a.abs()>10000.0){return Err(InputError::InvalidInput);}\nOk(ids.iter().zip(positions).map(|(i,pos)|table[*i].iter().zip(pos).map(|(a,b)|a+b).collect()).collect())',
]);
const attentionCode=samples('def scaled_attention(query: list[float], keys: list[list[float]], values: list[list[float]], allowed: list[bool]) -> dict[str, list[float]]','function scaledAttention(query, keys, values, allowed)','pub fn scaled_attention(query: &[f64], keys: &[Vec<f64>], values: &[Vec<f64>], allowed: &[bool]) -> Result<AttentionResult, InputError>',[
  'if not 1<=len(query)<=64 or not 1<=len(keys)<=64 or len(keys)!=len(values) or len(keys)!=len(allowed) or not values[0] or len(values[0])>64 or any(type(a) is not bool for a in allowed) or not any(allowed):\n    raise ValueError("Неверные оси/mask")\nif any(len(k)!=len(query) for k in keys) or any(len(v)!=len(values[0]) for v in values) or any(not math.isfinite(a) or abs(a)>100 for row in [query]+keys+values for a in row):\n    raise ValueError("Неверные shapes/values")\nscores=[sum(a*b for a,b in zip(query,k))/math.sqrt(len(query)) for k in keys]\nm=max(s for s,ok in zip(scores,allowed) if ok)\ne=[math.exp(s-m) if ok else 0.0 for s,ok in zip(scores,allowed)]\ntotal=sum(e); weights=[a/total for a in e]\nreturn {"weights":weights,"out":[sum(weights[j]*values[j][i] for j in range(len(keys))) for i in range(len(values[0]))]}',
  'if(!Array.isArray(query)||!Array.isArray(keys)||!Array.isArray(values)||!Array.isArray(allowed)||!query.length||query.length>64||!keys.length||keys.length>64||keys.length!==values.length||keys.length!==allowed.length||!Array.isArray(values[0])||!values[0].length||values[0].length>64||allowed.some(a=>typeof a!=="boolean")||!allowed.some(Boolean))throw new RangeError("Неверные оси/mask");\nif(keys.some(k=>!Array.isArray(k)||k.length!==query.length)||values.some(v=>!Array.isArray(v)||v.length!==values[0].length)||[...query,...keys.flat(),...values.flat()].some(a=>!Number.isFinite(a)||Math.abs(a)>100))throw new RangeError("Неверные shapes/values");\nconst scores=keys.map(k=>query.reduce((s,a,i)=>s+a*k[i],0)/Math.sqrt(query.length));\nconst m=Math.max(...scores.filter((_,i)=>allowed[i]));\nconst e=scores.map((s,i)=>allowed[i]?Math.exp(s-m):0),total=e.reduce((s,a)=>s+a,0),weights=e.map(a=>a/total);\nreturn {weights,out:values[0].map((_,i)=>values.reduce((s,v,j)=>s+weights[j]*v[i],0))};',
  'if query.is_empty()||query.len()>64||keys.is_empty()||keys.len()>64||keys.len()!=values.len()||keys.len()!=allowed.len()||values[0].is_empty()||values[0].len()>64||!allowed.iter().any(|a|*a){return Err(InputError::InvalidInput);}\nif keys.iter().any(|k|k.len()!=query.len())||values.iter().any(|v|v.len()!=values[0].len())||query.iter().chain(keys.iter().flatten()).chain(values.iter().flatten()).any(|a|!a.is_finite()||a.abs()>100.0){return Err(InputError::InvalidInput);}\nlet scores:Vec<f64>=keys.iter().map(|k|query.iter().zip(k).map(|(a,b)|a*b).sum::<f64>()/(query.len() as f64).sqrt()).collect();\nlet m=scores.iter().zip(allowed).filter(|(_,ok)|**ok).map(|(s,_)|*s).fold(f64::NEG_INFINITY,f64::max);\nlet e:Vec<f64>=scores.iter().zip(allowed).map(|(s,ok)|if *ok{(s-m).exp()}else{0.0}).collect();let total:f64=e.iter().sum();let weights:Vec<f64>=e.iter().map(|a|a/total).collect();\nlet out=(0..values[0].len()).map(|i|values.iter().zip(&weights).map(|(v,a)|a*v[i]).sum()).collect();\nOk(AttentionResult{weights,out})',
],'pub struct AttentionResult {pub weights:Vec<f64>,pub out:Vec<f64>}\n');
const headsCode=samples('def grouped_kv(q_heads: int, kv_heads: int, tokens: int, dim: int, bytes_per_value: int) -> dict[str, object]','function groupedKV(qHeads, kvHeads, tokens, dim, bytesPerValue)','pub fn grouped_kv(q_heads: usize, kv_heads: usize, tokens: usize, dim: usize, bytes_per_value: usize) -> Result<GroupedKV, InputError>',[
  'if any(not isinstance(a,int) for a in (q_heads,kv_heads,tokens,dim,bytes_per_value)) or not 1<=kv_heads<=q_heads<=64 or q_heads%kv_heads or not 1<=tokens<=1000000 or not 1<=dim<=10000 or bytes_per_value not in (2,4,8):\n    raise ValueError("Неверная конфигурация heads")\ngroup_size=q_heads//kv_heads\nreturn {"mapping":[i//group_size for i in range(q_heads)],"bytes":2*tokens*kv_heads*dim*bytes_per_value}',
  'if([qHeads,kvHeads,tokens,dim,bytesPerValue].some(a=>!Number.isInteger(a))||kvHeads<1||kvHeads>qHeads||qHeads>64||qHeads%kvHeads||tokens<1||tokens>1e6||dim<1||dim>1e4||![2,4,8].includes(bytesPerValue))throw new RangeError("Неверная конфигурация heads");\nconst groupSize=qHeads/kvHeads;\nreturn {mapping:Array.from({length:qHeads},(_,i)=>Math.floor(i/groupSize)),bytes:2*tokens*kvHeads*dim*bytesPerValue};',
  'if kv_heads==0||kv_heads>q_heads||q_heads>64||q_heads%kv_heads!=0||tokens==0||tokens>1000000||dim==0||dim>10000||![2,4,8].contains(&bytes_per_value){return Err(InputError::InvalidInput);}\nlet group_size=q_heads/kv_heads;\nOk(GroupedKV{mapping:(0..q_heads).map(|i|(i/group_size) as f64).collect(),bytes:(2*tokens*kv_heads*dim*bytes_per_value) as f64})',
],'pub struct GroupedKV {pub mapping:Vec<f64>,pub bytes:f64}\n');
const groupedMixCode=samples('def grouped_mix(weights: list[list[float]], values: list[list[float]]) -> list[float]','function groupedMix(weights, values)','pub fn grouped_mix(weights: &[Vec<f64>], values: &[Vec<f64>]) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(values)<=len(weights)<=64 or len(weights)%len(values) or not values[0] or len(values[0])>64:\n    raise ValueError("Неверное число heads/tokens")\nn=len(values[0])\nif any(len(row)!=n for row in weights+values) or any(not math.isfinite(a) or abs(a)>100 for row in weights+values for a in row) or any(any(a<0 for a in row) or abs(sum(row)-1)>1e-10 for row in weights):\n    raise ValueError("Неверные weights/values")\ngroup=len(weights)//len(values)\nreturn [sum(a*v for a,v in zip(row,values[h//group])) for h,row in enumerate(weights)]',
  'if(!Array.isArray(weights)||!Array.isArray(values)||!values.length||weights.length<values.length||weights.length>64||weights.length%values.length||!Array.isArray(values[0])||!values[0].length||values[0].length>64)throw new RangeError("Неверное число heads/tokens");\nconst n=values[0].length;if([...weights,...values].some(row=>!Array.isArray(row)||row.length!==n)||[...weights.flat(),...values.flat()].some(a=>!Number.isFinite(a)||Math.abs(a)>100)||weights.some(row=>row.some(a=>a<0)||Math.abs(row.reduce((s,a)=>s+a,0)-1)>1e-10))throw new RangeError("Неверные weights/values");\nconst group=weights.length/values.length;\nreturn weights.map((row,h)=>row.reduce((s,a,i)=>s+a*values[Math.floor(h/group)][i],0));',
  'if values.is_empty()||weights.len()<values.len()||weights.len()>64||weights.len()%values.len()!=0||values[0].is_empty()||values[0].len()>64{return Err(InputError::InvalidInput);}\nlet n=values[0].len();if weights.iter().chain(values).any(|row|row.len()!=n)||weights.iter().chain(values).flatten().any(|a|!a.is_finite()||a.abs()>100.0)||weights.iter().any(|row|row.iter().any(|a|*a<0.0)||(row.iter().sum::<f64>()-1.0).abs()>1e-10){return Err(InputError::InvalidInput);}\nlet group=weights.len()/values.len();\nOk(weights.iter().enumerate().map(|(h,row)|row.iter().zip(&values[h/group]).map(|(a,v)|a*v).sum()).collect())',
]);
const ropeCode=samples('def rope(x: list[float], pos: int, base: float) -> list[float]','function rope(x, pos, base)','pub fn rope(x: &[f64], pos: usize, base: f64) -> Result<Vec<f64>, InputError>',[
  'if not 2<=len(x)<=64 or len(x)%2 or not isinstance(pos,int) or not 0<=pos<=1000000 or not math.isfinite(base) or not 1<=base<=1000000 or any(not math.isfinite(a) or abs(a)>100 for a in x):\n    raise ValueError("RoPE требует чётную ширину и finite inputs")\nresult=[]\nfor i in range(0,len(x),2):\n    angle=pos*base**(-i/len(x));c=math.cos(angle);s=math.sin(angle)\n    result.extend([x[i]*c-x[i+1]*s,x[i]*s+x[i+1]*c])\nreturn result',
  'if(!Array.isArray(x)||x.length<2||x.length>64||x.length%2||!Number.isInteger(pos)||pos<0||pos>1e6||!Number.isFinite(base)||base<1||base>1e6||x.some(a=>!Number.isFinite(a)||Math.abs(a)>100))throw new RangeError("Неверные RoPE inputs");\nconst result=[];for(let i=0;i<x.length;i+=2){const angle=pos*base**(-i/x.length),c=Math.cos(angle),s=Math.sin(angle);result.push(x[i]*c-x[i+1]*s,x[i]*s+x[i+1]*c);}\nreturn result;',
  'if x.len()<2||x.len()>64||x.len()%2!=0||pos>1000000||!base.is_finite()||!(1.0..=1000000.0).contains(&base)||x.iter().any(|a|!a.is_finite()||a.abs()>100.0){return Err(InputError::InvalidInput);}\nlet mut result=Vec::new();for i in (0..x.len()).step_by(2){let angle=pos as f64*base.powf(-(i as f64)/x.len() as f64);let(c,s)=(angle.cos(),angle.sin());result.push(x[i]*c-x[i+1]*s);result.push(x[i]*s+x[i+1]*c);}\nOk(result)',
]);
const sinusoidalCode=samples('def sinusoidal_position(width: int, pos: int, base: float) -> list[float]','function sinusoidalPosition(width, pos, base)','pub fn sinusoidal_position(width: usize, pos: usize, base: f64) -> Result<Vec<f64>, InputError>',[
  'if not isinstance(width,int) or not 2<=width<=64 or width%2 or not isinstance(pos,int) or not 0<=pos<=1000000 or not math.isfinite(base) or not 1<=base<=1000000:\n    raise ValueError("Неверная positional configuration")\nresult=[]\nfor i in range(0,width,2):\n    angle=pos*base**(-i/width)\n    result.extend([math.sin(angle),math.cos(angle)])\nreturn result',
  'if(!Number.isInteger(width)||width<2||width>64||width%2||!Number.isInteger(pos)||pos<0||pos>1e6||!Number.isFinite(base)||base<1||base>1e6)throw new RangeError("Неверная positional configuration");\nconst result=[];for(let i=0;i<width;i+=2){const angle=pos*base**(-i/width);result.push(Math.sin(angle),Math.cos(angle));}return result;',
  'if width<2||width>64||width%2!=0||pos>1000000||!base.is_finite()||!(1.0..=1000000.0).contains(&base){return Err(InputError::InvalidInput);}\nlet mut result=Vec::new();for i in (0..width).step_by(2){let angle=pos as f64*base.powf(-(i as f64)/width as f64);result.push(angle.sin());result.push(angle.cos());}Ok(result)',
]);
function normCode(rms:boolean):Samples{
  return samples(`def ${rms?'rms_norm':'layer_norm'}(x: list[float], eps: float) -> list[float]`,`function ${rms?'rmsNorm':'layerNorm'}(x, eps)`,`pub fn ${rms?'rms_norm':'layer_norm'}(x: &[f64], eps: f64) -> Result<Vec<f64>, InputError>`,[
    `if not 1<=len(x)<=64 or any(not math.isfinite(a) or abs(a)>10000 for a in x) or not math.isfinite(eps) or not 1e-12<=eps<=1:\n    raise ValueError("Неверная normalization")\nmean=${rms?'0.0':'sum(x)/len(x)'}\nscale=math.sqrt(sum((a-mean)**2 for a in x)/len(x)+eps)\nreturn [(a-mean)/scale for a in x]`,
    `if(!Array.isArray(x)||!x.length||x.length>64||x.some(a=>!Number.isFinite(a)||Math.abs(a)>10000)||!Number.isFinite(eps)||eps<1e-12||eps>1)throw new RangeError("Неверная normalization");\nconst mean=${rms?'0':'x.reduce((s,a)=>s+a,0)/x.length'};\nconst scale=Math.sqrt(x.reduce((s,a)=>s+(a-mean)**2,0)/x.length+eps);return x.map(a=>(a-mean)/scale);`,
    `if x.is_empty()||x.len()>64||x.iter().any(|a|!a.is_finite()||a.abs()>10000.0)||!eps.is_finite()||!(1e-12..=1.0).contains(&eps){return Err(InputError::InvalidInput);}\nlet mean=${rms?'0.0':'x.iter().sum::<f64>()/x.len() as f64'};let scale=(x.iter().map(|a|(a-mean).powi(2)).sum::<f64>()/x.len() as f64+eps).sqrt();Ok(x.iter().map(|a|(a-mean)/scale).collect())`,
  ]);
}
const residualCode=samples('def residual_backward(incoming: list[float], local: list[float]) -> list[float]','function residualBackward(incoming, local)','pub fn residual_backward(incoming: &[f64], local: &[f64]) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(incoming)<=64 or len(incoming)!=len(local) or any(not math.isfinite(a) or abs(a)>10000 for a in incoming+local):\n    raise ValueError("Неверные gradients")\nreturn [g*(1+d) for g,d in zip(incoming,local)]',
  'if(!Array.isArray(incoming)||!Array.isArray(local)||!incoming.length||incoming.length>64||incoming.length!==local.length||[...incoming,...local].some(a=>!Number.isFinite(a)||Math.abs(a)>10000))throw new RangeError("Неверные gradients");return incoming.map((g,i)=>g*(1+local[i]));',
  'if incoming.is_empty()||incoming.len()>64||incoming.len()!=local.len()||incoming.iter().chain(local).any(|a|!a.is_finite()||a.abs()>10000.0){return Err(InputError::InvalidInput);}\nOk(incoming.iter().zip(local).map(|(g,d)|g*(1.0+d)).collect())',
]);
const ffnCode=samples('def ffn_scalar(x: float, w1: float, b1: float, w2: float, b2: float) -> float','function ffnScalar(x, w1, b1, w2, b2)','pub fn ffn_scalar(x: f64, w1: f64, b1: f64, w2: f64, b2: f64) -> Result<f64, InputError>',[
  'if any(not math.isfinite(a) or abs(a)>100 for a in (x,w1,b1,w2,b2)):\n    raise ValueError("Неверный FFN fragment")\nreturn w2*max(0.0,w1*x+b1)+b2',
  'if([x,w1,b1,w2,b2].some(a=>!Number.isFinite(a)||Math.abs(a)>100))throw new RangeError("Неверный FFN fragment");return w2*Math.max(0,w1*x+b1)+b2;',
  'if [x,w1,b1,w2,b2].iter().any(|a|!a.is_finite()||a.abs()>100.0){return Err(InputError::InvalidInput);}\nOk(w2*(w1*x+b1).max(0.0)+b2)',
]);
const maskCode=samples('def attention_mask(nq: int, nk: int, kind: str) -> list[list[bool]]','function attentionMask(nq, nk, kind)','pub fn attention_mask(nq: usize, nk: usize, kind: &str) -> Result<Vec<Vec<bool>>, InputError>',[
  'if not isinstance(nq,int) or not isinstance(nk,int) or not 1<=nq<=64 or not 1<=nk<=64 or kind not in ("self","causal","cross") or (kind!="cross" and nq!=nk):\n    raise ValueError("Неверная mask configuration")\nreturn [[j<=i if kind=="causal" else True for j in range(nk)] for i in range(nq)]',
  'if(!Number.isInteger(nq)||!Number.isInteger(nk)||nq<1||nq>64||nk<1||nk>64||!["self","causal","cross"].includes(kind)||(kind!=="cross"&&nq!==nk))throw new RangeError("Неверная mask configuration");return Array.from({length:nq},(_,i)=>Array.from({length:nk},(_,j)=>kind!=="causal"||j<=i));',
  'if nq==0||nq>64||nk==0||nk>64||!["self","causal","cross"].contains(&kind)||(kind!="cross"&&nq!=nk){return Err(InputError::InvalidInput);}\nOk((0..nq).map(|i|(0..nk).map(|j|kind!="causal"||j<=i).collect()).collect())',
]);
const cacheCode=samples('def append_cache(keys: list[list[float]], values: list[list[float]], new_key: list[float], new_value: list[float], pos: int) -> dict[str, list[list[float]]]','function appendCache(keys, values, newKey, newValue, pos)','pub fn append_cache(keys: &[Vec<f64>], values: &[Vec<f64>], new_key: &[f64], new_value: &[f64], pos: usize) -> Result<KVCache, InputError>',[
  'if len(keys)!=len(values) or len(keys)>=64 or not isinstance(pos,int) or pos!=len(keys) or not 1<=len(new_key)<=64 or not 1<=len(new_value)<=64 or any(len(k)!=len(new_key) for k in keys) or any(len(v)!=len(new_value) for v in values) or any(not math.isfinite(a) or abs(a)>100 for row in keys+values+[new_key,new_value] for a in row):\n    raise ValueError("Неверный cache position/shapes")\nreturn {"keys":[row.copy() for row in keys]+[new_key.copy()],"values":[row.copy() for row in values]+[new_value.copy()]}',
  'if(!Array.isArray(keys)||!Array.isArray(values)||!Array.isArray(newKey)||!Array.isArray(newValue)||keys.length!==values.length||keys.length>=64||!Number.isInteger(pos)||pos!==keys.length||!newKey.length||newKey.length>64||!newValue.length||newValue.length>64||keys.some(k=>!Array.isArray(k)||k.length!==newKey.length)||values.some(v=>!Array.isArray(v)||v.length!==newValue.length)||[...keys.flat(),...values.flat(),...newKey,...newValue].some(a=>!Number.isFinite(a)||Math.abs(a)>100))throw new RangeError("Неверный cache position/shapes");return {keys:[...keys.map(row=>[...row]),[...newKey]],values:[...values.map(row=>[...row]),[...newValue]]};',
  'if keys.len()!=values.len()||keys.len()>=64||pos!=keys.len()||new_key.is_empty()||new_key.len()>64||new_value.is_empty()||new_value.len()>64||keys.iter().any(|k|k.len()!=new_key.len())||values.iter().any(|v|v.len()!=new_value.len())||keys.iter().chain(values).flatten().chain(new_key).chain(new_value).any(|a|!a.is_finite()||a.abs()>100.0){return Err(InputError::InvalidInput);}\nlet mut k=keys.to_vec();let mut v=values.to_vec();k.push(new_key.to_vec());v.push(new_value.to_vec());Ok(KVCache{keys:k,values:v})',
],'pub struct KVCache {pub keys:Vec<Vec<f64>>,pub values:Vec<Vec<f64>>}\n');
const samplingCode=samples('def sampling_distribution(logits: list[float], temperature: float, top_k: int, top_p: float) -> list[float]','function samplingDistribution(logits, temperature, topK, topP)','pub fn sampling_distribution(logits: &[f64], temperature: f64, top_k: usize, top_p: f64) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(logits)<=64 or any(not math.isfinite(a) or abs(a)>100 for a in logits) or not math.isfinite(temperature) or not .1<=temperature<=10 or not isinstance(top_k,int) or not 1<=top_k<=len(logits) or not math.isfinite(top_p) or not 0<top_p<=1:\n    raise ValueError("Неверные sampling controls")\norder=sorted(range(len(logits)),key=lambda i:(-logits[i],i))[:top_k]\nm=max(logits[i]/temperature for i in order)\ne=[math.exp(logits[i]/temperature-m) for i in order];total=sum(e)\nweights=[a/total for a in e]\nkeep=[];cumulative=0.0\nfor i,p in zip(order,weights):\n    keep.append((i,p));cumulative+=p\n    if cumulative>=top_p:break\nnormalizer=sum(p for i,p in keep);result=[0.0]*len(logits)\nfor i,p in keep:result[i]=p/normalizer\nreturn result',
  'if(!Array.isArray(logits)||!logits.length||logits.length>64||logits.some(a=>!Number.isFinite(a)||Math.abs(a)>100)||!Number.isFinite(temperature)||temperature<.1||temperature>10||!Number.isInteger(topK)||topK<1||topK>logits.length||!Number.isFinite(topP)||topP<=0||topP>1)throw new RangeError("Неверные sampling controls");\nconst order=logits.map((_,i)=>i).sort((i,j)=>logits[j]-logits[i]||i-j).slice(0,topK);\nconst m=Math.max(...order.map(i=>logits[i]/temperature)),e=order.map(i=>Math.exp(logits[i]/temperature-m)),total=e.reduce((s,a)=>s+a,0),weights=e.map(a=>a/total);\nlet count=0,cumulative=0;do{cumulative+=weights[count++];}while(count<order.length&&cumulative<topP);\nconst norm=weights.slice(0,count).reduce((s,a)=>s+a,0),result=Array(logits.length).fill(0);for(let j=0;j<count;j++)result[order[j]]=weights[j]/norm;return result;',
  'if logits.is_empty()||logits.len()>64||logits.iter().any(|a|!a.is_finite()||a.abs()>100.0)||!temperature.is_finite()||!(0.1..=10.0).contains(&temperature)||top_k==0||top_k>logits.len()||!top_p.is_finite()||top_p<=0.0||top_p>1.0{return Err(InputError::InvalidInput);}\nlet mut order:Vec<usize>=(0..logits.len()).collect();order.sort_by(|i,j|logits[*j].partial_cmp(&logits[*i]).unwrap().then(i.cmp(j)));order.truncate(top_k);\nlet m=order.iter().map(|i|logits[*i]/temperature).fold(f64::NEG_INFINITY,f64::max);let e:Vec<f64>=order.iter().map(|i|(logits[*i]/temperature-m).exp()).collect();let total:f64=e.iter().sum();let weights:Vec<f64>=e.iter().map(|a|a/total).collect();\nlet(mut count,mut cumulative)=(0,0.0);while count<order.len(){cumulative+=weights[count];count+=1;if cumulative>=top_p{break;}}\nlet norm:f64=weights[..count].iter().sum();let mut result=vec![0.0;logits.len()];for j in 0..count{result[order[j]]=weights[j]/norm;}Ok(result)',
]);
const sampleCode=samples('def sample_cdf(probabilities: list[float], u: float) -> float','function sampleCDF(probabilities, u)','pub fn sample_cdf(probabilities: &[f64], u: f64) -> Result<f64, InputError>',[
  'if not 1<=len(probabilities)<=64 or any(not math.isfinite(a) or a<0 for a in probabilities) or abs(sum(probabilities)-1)>1e-10 or not math.isfinite(u) or not 0<=u<1:\n    raise ValueError("Неверная probability/CDF contract")\ncumulative=0.0\nfor i,p in enumerate(probabilities):\n    cumulative+=p\n    if p>0 and u<cumulative:return i\nreturn max(i for i,p in enumerate(probabilities) if p>0)',
  'if(!Array.isArray(probabilities)||!probabilities.length||probabilities.length>64||probabilities.some(a=>!Number.isFinite(a)||a<0)||Math.abs(probabilities.reduce((s,a)=>s+a,0)-1)>1e-10||!Number.isFinite(u)||u<0||u>=1)throw new RangeError("Неверная probability/CDF contract");\nlet cumulative=0,last=0;for(let i=0;i<probabilities.length;i++){const p=probabilities[i];if(p>0)last=i;cumulative+=p;if(p>0&&u<cumulative)return i;}return last;',
  'if probabilities.is_empty()||probabilities.len()>64||probabilities.iter().any(|a|!a.is_finite()||*a<0.0)||(probabilities.iter().sum::<f64>()-1.0).abs()>1e-10||!u.is_finite()||!(0.0..1.0).contains(&u){return Err(InputError::InvalidInput);}\nlet(mut cumulative,mut last)=(0.0,0);for(i,p)in probabilities.iter().enumerate(){if *p>0.0{last=i;}cumulative+=p;if *p>0.0&&u<cumulative{return Ok(i as f64);}}Ok(last as f64)',
]);
const teacherCode=samples('def shifted_targets(ids: list[int]) -> list[list[int]]','function shiftedTargets(ids)','pub fn shifted_targets(ids: &[usize]) -> Result<Vec<Vec<f64>>, InputError>',[
  'if not 2<=len(ids)<=64 or any(not isinstance(i,int) or not 0<=i<=1000000 for i in ids):\n    raise ValueError("Неверные token IDs")\nreturn [ids[:-1],ids[1:]]',
  'if(!Array.isArray(ids)||ids.length<2||ids.length>64||ids.some(i=>!Number.isInteger(i)||i<0||i>1e6))throw new RangeError("Неверные token IDs");return [ids.slice(0,-1),ids.slice(1)];',
  'if ids.len()<2||ids.len()>64||ids.iter().any(|i|*i>1000000){return Err(InputError::InvalidInput);}\nOk(vec![ids[..ids.len()-1].iter().map(|i|*i as f64).collect(),ids[1..].iter().map(|i|*i as f64).collect()])',
]);
const headGradCode=samples('def head_gradient(features: list[float], weights: list[list[float]], target: int) -> list[list[float]]','function headGradient(features, weights, target)','pub fn head_gradient(features: &[f64], weights: &[Vec<f64>], target: usize) -> Result<Vec<Vec<f64>>, InputError>',[
  'if not 1<=len(features)<=64 or not 2<=len(weights)<=64 or not isinstance(target,int) or not 0<=target<len(weights) or any(len(row)!=len(features) for row in weights) or any(not math.isfinite(a) or abs(a)>100 for row in weights+[features] for a in row):\n    raise ValueError("Неверная head shape/target")\nlogits=[sum(a*b for a,b in zip(features,row)) for row in weights]\nm=max(logits);e=[math.exp(z-m) for z in logits];total=sum(e)\nreturn [[(a/total-(1 if j==target else 0))*h for h in features] for j,a in enumerate(e)]',
  'if(!Array.isArray(features)||!Array.isArray(weights)||!features.length||features.length>64||weights.length<2||weights.length>64||!Number.isInteger(target)||target<0||target>=weights.length||weights.some(row=>!Array.isArray(row)||row.length!==features.length)||[...weights.flat(),...features].some(a=>!Number.isFinite(a)||Math.abs(a)>100))throw new RangeError("Неверная head shape/target");\nconst logits=weights.map(row=>features.reduce((s,a,i)=>s+a*row[i],0)),m=Math.max(...logits),e=logits.map(z=>Math.exp(z-m)),total=e.reduce((s,a)=>s+a,0);return e.map((a,j)=>features.map(h=>(a/total-(j===target?1:0))*h));',
  'if features.is_empty()||features.len()>64||weights.len()<2||weights.len()>64||target>=weights.len()||weights.iter().any(|row|row.len()!=features.len())||weights.iter().flatten().chain(features).any(|a|!a.is_finite()||a.abs()>100.0){return Err(InputError::InvalidInput);}\nlet logits:Vec<f64>=weights.iter().map(|row|features.iter().zip(row).map(|(a,b)|a*b).sum()).collect();let m=logits.iter().copied().fold(f64::NEG_INFINITY,f64::max);let e:Vec<f64>=logits.iter().map(|z|(z-m).exp()).collect();let total:f64=e.iter().sum();Ok(e.iter().enumerate().map(|(j,a)|features.iter().map(|h|(a/total-if j==target{1.0}else{0.0})*h).collect()).collect())',
]);

